KG_CODE("f:src/autoskill/handlers.py","\"\"\"Method handlers. Thin glue between the wire protocol and the executors.\n\nKept separate from `daemon.py` so that routing, policy and lifetime stay\nreadable on their own, and so a handler can be tested without a socket.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport base64\nimport os\nimport tempfile\nimport time\nfrom pathlib import Path\nfrom typing import TYPE_CHECKING, Any\n\nfrom . import history as _history\nfrom . import memspace, savedpaths\nfrom .desktop import actions, docgen, ledger, uia, vision\nfrom .desktop import refs as _refs\nfrom .desktop.executor import uia_call\nfrom .protocol import EffectState, ErrorCode, Method, ProtocolError\nfrom .ports import PerceptionReporter\nfrom .contracts import Component\nfrom .contracts.perception import PerceptionMode, PerceptionSummary\n\nif TYPE_CHECKING:\n    from .daemon import Daemon, Session\n\n\ndef _required(session: \"Session | None\") -> \"Session\":\n    if session is None:\n        raise ProtocolError(ErrorCode.NO_SESSION, \"this handler requires an active session\")\n    return session\n\n\ndef register(d: \"Daemon\") -> None:\n    from . import host\n    d.register(Method.HOST_CAPABILITIES.value, lambda s, p: host.capabilities())\n    d.register(Method.HOST_RUN.value, lambda s, p: host.run(**{**p, \"run\": d.run_control.generation}))\n    d.register(Method.HOST_PROCESSES.value, lambda s, p: host.processes(int(p.get(\"limit\", 100))))\n    d.register(Method.MEMORY_DIAGNOSTICS.value, lambda s, p: d.diagnostics.read(p.get(\"session\", \"\"), int(p.get(\"limit\", 50))))\n    d.register(Method.WORKFLOW_SAVE.value, lambda s, p: d.diagnostics.save_workflow(p[\"name\"], p[\"session\"]))\n    d.register(Method.WORKFLOW_LOAD.value, lambda s, p: d.diagnostics.load_workflow(p[\"name\"]))\n    d.register(Method.DESKTOP_RECORD_START.value, lambda s, p: _record_start(d, _required(s), p))\n    d.register(Method.DESKTOP_RECORD_STOP.value, lambda s, p: _record_stop(d, _required(s)))\n    from .watchdog import Watchdog, read_alerts\n    from .contracts.monitoring import BridgeHealth, HealthRequest\n    from .orchestrator.monitoring import AuditActivity, NativeBridgeHealth, WatchdogGateway\n    watchdog = Watchdog(d.home, activity=AuditActivity(d.events), bridge_health=NativeBridgeHealth())\n    monitor = WatchdogGateway(d.events, watchdog)\n    def check_watch(s, p):\n        report = monitor.check(HealthRequest(bool(p.get(\"check_bridge\", True))))\n        result = {\"effect_state\": \"none\", \"at\": report.measured_at,\n                  \"verdict\": report.verdict.value, \"reason\": report.reason,\n                  **{metric.name: metric.value for metric in report.metrics},\n                  \"alerts\": read_alerts(d.home)[\"alerts\"]}\n        if report.bridge is not BridgeHealth.NOT_CHECKED:\n            result[\"bridge\"] = report.bridge.value\n        return result\n    d.register(Method.WATCH_CHECK.value, check_watch)\n    d.register(Method.WATCH_ALERTS.value, lambda s, p: read_alerts(d.home, int(p.get(\"limit\", 20))))\n    from .orchestrator.environment import environment_wire\n    d.register(Method.ENVIRONMENT.value, lambda s, p: environment_wire(d.environment))\n    from .orchestrator.workflow_memory import recall_wire, remember_wire\n    d.register(Method.MEMORY_RECALL.value, lambda s, p: recall_wire(d.workflow_evidence, p[\"workflow\"], int(p.get(\"limit\", 5))))\n    d.register(Method.MEMORY_REMEMBER.value, lambda s, p: remember_wire(d.workflow_evidence,\n        p[\"workflow\"], p[\"method\"], p[\"outcome\"]))\n    d.register(Method.SYSTEM_PING.value, lambda s, p: {\"pong\": True})\n    d.register(Method.SYSTEM_STATUS.value, lambda s, p: d.status())\n    d.register(Method.SYSTEM_DOCTOR.value, lambda s, p: _doctor(d))\n    d.register(Method.HISTORY_LIST.value,\n               lambda s, p: _history.list_records(d.home,\n                                                  int(p.get(\"limit\", 20))))\n    d.register(Method.HISTORY_SHOW.value,\n               lambda s, p: _history.show_record(d.home, str(p[\"id\"])))\n    d.register(Method.HISTORY_FORGET.value,\n               lambda s, p: _history.forget(d.home, str(p[\"id\"])))\n    d.register(Method.FLOW_LIST.value, lambda s, p: _flow_list())\n    d.register(Method.FLOW_VALIDATE.value,\n               lambda s, p: _flow_validate(str(p[\"profile\"])))\n    d.register(Method.FLOW_ANALYSE.value, lambda s, p: _flow_analyse(d, s, p))\n    d.register(Method.FLOW_STATUS.value,\n               lambda s, p: _flow_status(d, str(p[\"profile\"])))\n    d.register(Method.FLOW_START.value, lambda s, p: _flow_start(d, p))\n    d.register(Method.FLOW_RECONCILE.value,\n               lambda s, p: _flow_reconcile(d, str(p[\"profile\"])))\n    d.register(Method.SYSTEM_WATCH_STATUS.value,\n               lambda s, p: _watch_status(d))\n    d.register(Method.SYSTEM_WATCH_TIMELINE.value,\n               lambda s, p: _watch_timeline(d, int(p.get(\"limit\", 50))))\n    d.register(Method.SYSTEM_SHUTDOWN.value, lambda s, p: (_shutdown(d)))\n\n    d.register(Method.SESSION_START.value, lambda s, p: _session_start(d, p))\n    d.register(Method.SESSION_STOP.value, lambda s, p: _session_stop(d, p))\n    d.register(Method.SESSION_LIST.value, lambda s, p: _session_list(d, p))\n    d.register(Method.SESSION_MEMORIES.value,\n               lambda s, p: {\"effect_state\": \"none\", \"spaces\": memspace.list_spaces(d.home)})\n\n    # Saved paths: recalled only by exact name (#paths, #path NAME; savedpaths.py).\n    d.register(Method.PATH_LIST.value,\n               lambda s, p: {\"effect_state\": \"none\", \"paths\": savedpaths.list_paths(d.sites, home=d.home)})\n    d.register(Method.PATH_SHOW.value,\n               lambda s, p: savedpaths.show(d.sites, str(p.get(\"name\") or \"\"), p.get(\"site\"), home=d.home))\n    d.register(Method.PATH_RUN.value, lambda s, p: _path_run(d, s, p))\n\n    d.register(Method.CONFIG_GET.value,\n               lambda s, p: {\"policy\": d.policy.to_dict()})\n    d.register(Method.CONFIG_SET.value, lambda s, p: _config_set(d, p))\n\n    d.register(Method.DESKTOP_WINDOWS.value,\n               lambda s, p: uia_call(lambda: _windows(p)))\n    d.register(Method.DESKTOP_OBSERVE.value,\n               lambda s, p: uia_call(lambda: _observe(d, _required(s), p, reporter=d.perception)))\n    d.register(Method.DESKTOP_FOCUS.value,\n               lambda s, p: uia_call(lambda: _focus(_required(s), p)))\n    d.register(Method.DESKTOP_CLICK.value,\n               lambda s, p: uia_call(lambda: _click(d, _required(s), p)))\n    d.register(Method.DESKTOP_TYPE.value,\n               lambda s, p: uia_call(lambda: actions.type_text(\n                   _required(s).ref_store, p[\"text\"], ref=p.get(\"ref\"),\n                   method=p.get(\"method\", \"auto\"),\n                   window=p.get(\"window\"),\n                   # B8: CUA type_text.delay_ms - forwarded verbatim; absent\n                   # stays absent (CUA applies its own default 30).\n                   delay_ms=p.get(\"delay_ms\"), x=p.get(\"x\"), y=p.get(\"y\"),\n                   **_delivery(p))))\n    d.register(Method.DESKTOP_KEY.value,\n               lambda s, p: uia_call(lambda: actions.press_key(\n                   _required(s).ref_store, p[\"keys\"], ref=p.get(\"ref\"),\n                   window=p.get(\"window\"), x=p.get(\"x\"), y=p.get(\"y\"),\n                   scope=p.get(\"scope\"), **_delivery(p))))\n    d.register(Method.DESKTOP_SET_VALUE.value,\n               lambda s, p: uia_call(lambda: actions.set_value(\n                   _required(s).ref_store, p[\"ref\"], p[\"value\"],\n                   **_delivery(p))))\n    # B25b-r (D1/D2): one adapter run_steps call under the existing\n    # contracts; daemon-only (no catalogue surface yet - the\n    # test_completion invariant carries the named exemption).\n    from .desktop.batch import run_batch\n    d.register(\"desktop.batch\", lambda s, p: run_batch(d, _required(s), p))\n    d.register(Method.DESKTOP_SCROLL.value,\n               lambda s, p: uia_call(lambda: actions.scroll(\n                   _required(s).ref_store, ref=p.get(\"ref\"),\n                   direction=p.get(\"direction\", \"down\"),\n                   amount=int(p.get(\"amount\", 3)), by=p.get(\"by\", \"line\"),\n                   window=p.get(\"window\"), x=p.get(\"x\"), y=p.get(\"y\"),\n                   **_delivery(p))))\n    d.register(Method.DESKTOP_DRAG.value,\n               lambda s, p: uia_call(lambda: actions.drag(\n                   _required(s).ref_store, **_drag_args(p))))\n    d.register(Method.DESKTOP_SCREENSHOT.value,\n               lambda s, p: uia_call(lambda: _screenshot(d, _required(s), p)))\n    d.register(Method.DESKTOP_ZOOM.value,\n               lambda s, p: uia_call(lambda: _zoom(d, _required(s), p)))\n    d.register(Method.DESKTOP_OPEN_APP.value,\n               lambda s, p: uia_call(lambda: _open_app(_required(s), p), timeout=300))\n    d.register(Method.DESKTOP_CLOSE_WINDOW.value,\n               lambda s, p: uia_call(lambda: actions.close_window(p[\"window\"])))\n    d.register(Method.DESKTOP_QUIT_APP.value,\n               lambda s, p: uia_call(lambda: actions.quit_app(\n                   str(p.get(\"process\") or \"\"), pid=p.get(\"pid\"), timeout=float(p.get(\"timeout\", 12))),\n                   timeout=180))\n    d.register(Method.DESKTOP_INVOKE_MENU.value,\n               lambda s, p: uia_call(lambda: _invoke_menu(d, _required(s), p)))\n    d.register(Method.DESKTOP_CLIPBOARD_READ.value,\n               lambda s, p: uia_call(lambda: _clipboard_read(d, _required(s), p)))\n    d.register(Method.DESKTOP_CLIPBOARD_WRITE.value,\n               lambda s, p: uia_call(lambda: _clipboard_write(d, _required(s), p)))\n    d.register(Method.DESKTOP_VERIFY_STATE.value,\n               lambda s, p: uia_call(lambda: _verify_state(d, _required(s), p)))\n    d.register(Method.DESKTOP_SET_WINDOW_FRAME.value,\n               lambda s, p: uia_call(lambda: _set_window_frame(d, _required(s), p)))\n    d.register(Method.DESKTOP_ACCESSIBILITY_TREE.value,\n               lambda s, p: uia_call(lambda: _accessibility_tree(d, _required(s), p)))\n    d.register(Method.DESKTOP_SCREEN_SIZE.value,\n               lambda s, p: uia_call(lambda: _screen_size(d, _required(s), p)))\n    d.register(Method.DESKTOP_CURSOR_POSITION.value,\n               lambda s, p: uia_call(lambda: _cursor_position(d, _required(s), p)))\n    d.register(Method.DESKTOP_MOVE_CURSOR.value,\n               lambda s, p: uia_call(lambda: _move_cursor(d, _required(s), p)))\n    d.register(Method.DESKTOP_COPY.value,\n               lambda s, p: actions.copy_paths(list(p.get(\"sources\") or []),\n                                               str(p.get(\"destination\") or \"\")))\n    d.register(Method.DESKTOP_TABLE_APPEND.value,\n               lambda s, p: ledger.table_append(\n                   str(p[\"file\"]), list(p.get(\"rows\") or []),\n                   header=p.get(\"header\"), sep=p.get(\"sep\") or \"\\t\",\n                   dedup_cols=p.get(\"dedup\")))\n    d.register(Method.DESKTOP_APPS.value,\n               lambda s, p: actions.installed_apps(p.get(\"find\"), p.get(\"class\")))\n    d.register(Method.DESKTOP_REPORT.value,\n               lambda s, p: docgen.build_docx(str(p[\"file\"]),\n                                              p.get(\"title\") or \"\",\n                                              list(p.get(\"blocks\") or [])))\n    d.register(Method.DESKTOP_TABLE_READ.value,\n               lambda s, p: ledger.table_read(str(p[\"file\"]),\n                                              limit=int(p.get(\"limit\", 50))))\n    d.register(Method.DESKTOP_TABLE_EXPORT.value,\n               lambda s, p: ledger.table_export(str(p[\"file\"]), str(p[\"destination\"])))\n\n    d.register(Method.DESKTOP_WAIT_WINDOW.value,\n               lambda s, p: uia_call(lambda: actions.wait_for_window(\n                   p[\"window\"], timeout=float(p.get(\"timeout\", 20)),\n                   gone=bool(p.get(\"gone\"))),\n                   timeout=float(p.get(\"timeout\", 20)) + 30))\n    d.register(Method.DESKTOP_WAIT_REF.value,\n               lambda s, p: uia_call(lambda: actions.wait_for_ref(\n                   _required(s).ref_store, p[\"name\"], window=p.get(\"window\"),\n                   timeout=float(p.get(\"timeout\", 20))),\n                   timeout=float(p.get(\"timeout\", 20)) + 30))\n    d.register(Method.BROWSER_WAIT.value,\n               lambda s, p: _page_t(_required(s), p).wait_for(\n                   p.get(\"text\"), timeout=float(p.get(\"timeout\", 20))))\n\n    d.register(Method.BROWSER_SELECT.value,\n               lambda s, p: _page_t(_required(s), p).select_option(p[\"ref\"], value=p.get(\"value\"),\n                                                        label=p.get(\"label\")))\n    d.register(Method.BROWSER_BACK.value,\n               lambda s, p: _page_t(_required(s), p).history(int(p.get(\"delta\", -1))))\n    d.register(Method.BROWSER_RELOAD.value,\n               lambda s, p: _page_t(_required(s), p).reload())\n    d.register(Method.BROWSER_DIALOG_POLICY.value,\n               lambda s, p: _dialog_policy(_page_t(_required(s), p), p))\n\n    d.register(Method.BROWSER_HOVER.value, lambda s, p: _page_t(_required(s), p).hover(p[\"ref\"]))\n    d.register(Method.BROWSER_GET_HTML.value,\n               lambda s, p: _page_t(_required(s), p).get_html(ref=p.get(\"ref\"),\n                                                  max_chars=int(p.get(\"max_chars\", 200000))))\n    d.register(Method.BROWSER_CONSOLE.value,\n               lambda s, p: _page_t(_required(s), p).console(int(p.get(\"limit\", 50))))\n\n    d.register(Method.BROWSER_EXTRACT.value,\n               lambda s, p: _page_t(_required(s), p).extract(p.get(\"kind\", \"text\"),\n                                                  ref=p.get(\"ref\"),\n                                                  max_chars=int(p.get(\"max_chars\", 20000))))\n    d.register(Method.BROWSER_POPUPS.value,\n               lambda s, p: _page_t(_required(s), p).popups(clear=bool(p.get(\"clear\"))))\n    d.register(Method.BROWSER_LIST.value, lambda s, p: _browser_list())\n\n    d.register(Method.BROWSER_TAB_NEW.value, lambda s, p: _tab_new(d, _required(s), p))\n    d.register(Method.BROWSER_TAB_LIST.value, lambda s, p: _tab_list(_required(s), p))\n    d.register(Method.BROWSER_TAB_SELECT.value, lambda s, p: _tab_select(_required(s), p))\n    d.register(Method.BROWSER_TAB_CLOSE.value, lambda s, p: _tab_close(_required(s), p))\n\n    d.register(Method.BROWSER_OPEN.value, lambda s, p: _browser_open(d, _required(s), p))\n    d.register(Method.BROWSER_NAVIGATE.value,\n               lambda s, p: _page_t(_required(s), p).navigate(p[\"url\"]))\n    d.register(Method.BROWSER_OBSERVE.value,\n               lambda s, p: _page_t(_required(s), p).observe(\n                   max_nodes=int(p.get(\"max_nodes\", 2500)),\n                   max_tokens=(int(p[\"max_tokens\"]) if p.get(\"max_tokens\")\n                               else None)))\n    d.register(Method.BROWSER_OBSERVE_MORE.value,\n               lambda s, p: _page_t(_required(s), p).more(\n                   int(p[\"cursor\"]) if p.get(\"cursor\") is not None else None,\n                   max_tokens=int(p.get(\"max_tokens\", 3000))))\n    d.register(Method.BROWSER_CLICK.value,\n               lambda s, p: _page_t(_required(s), p).click(p[\"ref\"],\n                                           clicks=int(p.get(\"clicks\", 1))))\n    d.register(Method.BROWSER_TYPE.value,\n               lambda s, p: _page_t(_required(s), p).type_text(p.get(\"ref\"), p[\"text\"],\n                                               clear=bool(p.get(\"clear\"))))\n    d.register(Method.BROWSER_KEY.value, lambda s, p: _page_t(_required(s), p).press(p[\"key\"]))\n    d.register(Method.BROWSER_SCROLL.value,\n               lambda s, p: _page_t(_required(s), p).scroll(delta_y=p.get(\"delta_y\"),\n                                            delta_x=p.get(\"delta_x\")))\n    d.register(Method.BROWSER_SCREENSHOT.value, lambda s, p: _browser_shot(_required(s), p))\n    d.register(Method.BROWSER_CLOSE.value, lambda s, p: _browser_close(_required(s), d.home))\n\n    d.register(Method.DESKTOP_EXTRACT.value,\n               lambda s, p: uia_call(lambda: _extract(d, _required(s), p)))\n\n    # Answering an approval is a control frame, not an ordinary action: it must\n    # never itself be subject to the policy it unblocks, or a confirmation\n    # could require a confirmation.\n    d.register(\"_confirm.answer\", lambda s, p: _confirm_answer(d, p))\n    # The owner's Kgrow.io dashboard buttons (runcontrol.py, dashboard/):\n    # control frames like the approval answer, never gated by the policy\n    # they control (safety/permissions.py).\n    d.register(\"_run.state\", lambda s, p: _run_state(d, p))\n    d.register(\"_run.pause\", lambda s, p: d.run_control.pause())\n    d.register(\"_run.resume\", lambda s, p: d.run_control.resume())\n    # db1: Stop ends everything the run left running; Clean (reset is its\n    # old name) clears the view; the server's own buttons are noted too.\n    d.register(\"_run.stop\", lambda s, p: d.run_control.stop(d.confirmations, daemon=d))\n    d.register(\"_run.approve\", lambda s, p: d.run_control.approve(\n        d.confirmations, str(p.get(\"token\") or \"\"), str(p.get(\"scope\") or \"once\")))\n    d.register(\"_run.repeat\", lambda s, p: d.run_control.set_repeat(int(p.get(\"count\", 1))))\n    d.register(\"_run.progress\", lambda s, p: _run_progress(d, p))\n    # db7 Item H: Play on an empty dashboard lists the saved workflows; Use puts one on the map, Delete removes it\n    d.register(\"_run.saved\", lambda s, p: {\"effect_state\": \"none\", \"paths\": savedpaths.list_paths(d.sites, d.home)})\n    d.register(\"_run.use\", lambda s, p: _run_use(d, p))\n    d.register(\"_run.forget_path\", lambda s, p: _run_forget_path(d, p))\n    d.register(\"_run.reset\", lambda s, p: _run_clean(d))\n    d.register(\"_run.clean\", lambda s, p: _run_clean(d))\n    d.register(\"_run.note\", lambda s, p: d.run_control.note_server(\n        str(p.get(\"action\") or \"\"), **{k: v for k, v in p.items() if k in (\"state\", \"name\")}))\n    d.register(\"_run.flow_register\", lambda s, p: _run_flow_register(d, p))\n    d.register(\"_run.import\", lambda s, p: _run_import(d, p))\n    d.register(\"_run.save\", lambda s, p: _run_save(d, p))\n    # db2: the studio reads a run's record and writes a saved workflow back.\n    d.register(\"_run.turns\", lambda s, p: _run_turns(d, p))\n    d.register(\"_run.workflow_put\", lambda s, p: _run_workflow_put(d, p))\n    d.register(\"_run.workflow_get\",                                  # db2: the studio's load, not a step of the run\n               lambda s, p: savedpaths.show(d.sites, str(p.get(\"name\") or \"\"), home=d.home))\n    d.register(\"_run.agents\", lambda s, p: _run_agents(d))           # db3: the agent CLIs this machine has\n    d.register(\"_run.agent_api\", lambda s, p: _run_agent_api(d, p))  # db6: the studio adds an API for any model\n    d.register(\"_run.test\", lambda s, p: _run_test(d, p))            # db3: the studio's Test\n    d.register(\"_run.agent_status\", lambda s, p: _run_agent_status(d, p))   # db7: is an agent or API on\n    d.register(\"_run.tool_help\", lambda s, p: _run_tool_help(p))     # db7: plain words for the node settings\n    d.register(\"_run.find_target\", lambda s, p: _run_find_target(d, p))   # db7 Phase 1: Check on screen / Choose\n    d.register(\"_run.workflow_file\", lambda s, p: _run_workflow_file(d, p))  # db7: the studio's Save to a folder\n    d.register(\"_run.play\", lambda s, p: _run_play(d))               # db6: the dashboard's Play\n    d.register(\"_run.record\", lambda s, p: _run_record(d, p))        # db8: the dashboard's Record button\n\n    d.register(Method.RB_STATUS.value, lambda s, p: d.rb.status())\n    d.register(Method.RB_TABS.value, lambda s, p: d.rb.list_tabs())\n    d.register(Method.RB_OPEN.value, lambda s, p: d.rb.open(str(p[\"url\"])))\n    d.register(Method.RB_ACTIVATE.value,\n               lambda s, p: d.rb.activate(p.get(\"tab_id\")))\n    d.register(Method.RB_NAVIGATE.value,\n               lambda s, p: d.rb.navigate(str(p[\"url\"]), p.get(\"tab_id\")))\n    d.register(Method.RB_OBSERVE.value,\n               lambda s, p: d.rb.observe(\n                   p.get(\"tab_id\"),\n                   max_tokens=(int(p[\"max_tokens\"]) if p.get(\"max_tokens\")\n                               else None),\n                   fallback=bool(p.get(\"fallback\")),\n                   ocr=bool(p.get(\"ocr\"))))\n    d.register(Method.RB_LOCATE.value,\n               lambda s, p: d.rb.locate(str(p[\"near\"]), p.get(\"tab_id\"),\n                                        nth=int(p.get(\"nth\") or 1),\n                                        pick=p.get(\"pick\")))\n    d.register(Method.RB_CLICK.value,\n               lambda s, p: d.rb.click(str(p[\"ref\"]), p.get(\"tab_id\")))\n    d.register(Method.RB_TYPE.value,\n               lambda s, p: d.rb.type_text(str(p[\"text\"]), p.get(\"ref\"),\n                                           p.get(\"tab_id\")))\n    d.register(Method.RB_KEY.value,\n               lambda s, p: d.rb.press(str(p[\"key\"]), p.get(\"tab_id\")))\n    d.register(Method.RB_UPLOAD.value,\n               lambda s, p: d.rb.upload(str(p[\"ref\"]),\n                                        list(p.get(\"files\") or []),\n                                        p.get(\"tab_id\")))\n    d.register(Method.RB_RELOAD.value,\n               lambda s, p: d.rb.reload(p.get(\"tab_id\")))\n    d.register(Method.RB_WAIT.value,\n               lambda s, p: d.rb.wait(str(p[\"name\"]), p.get(\"role\"),\n                                      float(p.get(\"timeout\", 20)),\n                                      p.get(\"tab_id\")))\n    d.register(Method.RB_CLOSE.value,\n               lambda s, p: d.rb.close(p.get(\"tab_id\")))\n    d.register(Method.RB_RESET.value, lambda s, p: d.rb.reset())\n    d.register(Method.RB_SCREENSHOT.value,\n               lambda s, p: d.rb.screenshot(p.get(\"tab_id\"), p.get(\"out\"),\n                                            with_overlay=bool(p.get(\"with_overlay\"))))\n    d.register(Method.RB_CUE.value,\n               lambda s, p: d.rb.cue(p.get(\"tab_id\"), **{\n                   k: v for k, v in p.items() if k != \"tab_id\"}))\n    d.register(Method.RB_OCR.value,\n               lambda s, p: d.rb.ocr(p.get(\"tab_id\"), lang=p.get(\"lang\"),\n                                     find=p.get(\"find\"),\n                                     nth=int(p.get(\"nth\") or 1)))\n    d.register(Method.RB_CLICK_AT.value,\n               lambda s, p: d.rb.click_at(float(p[\"x\"]), float(p[\"y\"]),\n                                          p.get(\"tab_id\"),\n                                          dry=bool(p.get(\"dry\"))))\n    d.register(Method.RB_ACT.value,\n               lambda s, p: d.rb.act(\n                   ref=p.get(\"ref\"), text=p.get(\"text\"),\n                   tab_id=p.get(\"tab_id\"), methods=p.get(\"methods\"),\n                   patience=(float(p[\"patience\"]) if p.get(\"patience\")\n                             else None),\n                   irreversible=bool(p.get(\"irreversible\")),\n                   reload_ok=not bool(p.get(\"no_reload\")),\n                   expect_appear=list(p.get(\"expect_appear\") or []),\n                   expect_gone=list(p.get(\"expect_gone\") or []),\n                   visual=not bool(p.get(\"no_visual\")),\n                   nth=int(p.get(\"nth\") or 1),\n                   near=p.get(\"near\"), pick=p.get(\"pick\"),\n                   expect_new_tab=bool(p.get(\"expect_new_tab\")),\n                   expect_download=p.get(\"expect_download\"),\n                   ensure=not bool(p.get(\"no_ensure\")),\n                   accept_weak=bool(p.get(\"accept_weak\"))))\n    d.register(Method.RB_VIDEO.value, lambda s, p: _knowing(d, d.rb.record_video(\n        p.get(\"tab_id\"), seconds=float(p.get(\"seconds\") or 10.0),\n        title=str(p.get(\"title\") or \"recording\"),\n        with_overlay=bool(p.get(\"with_overlay\")))))\n    d.register(Method.RB_ANALYSE.value, lambda s, p: _rb_analyse(d, p))\n    d.register(Method.RB_SELFRELOAD.value, lambda s, p: d.rb.selfreload())\n\n    d.register(Method.DESKTOP_OCR.value,\n               lambda s, p: uia_call(lambda: vision.ocr(\n                   _scratch_png(d, _required(s), \"ocr\"), window=p.get(\"window\"),\n                   lang=p.get(\"lang\"), find=p.get(\"find\"),\n                   nth=int(p.get(\"nth\") or 1)), timeout=180))\n    d.register(Method.DESKTOP_CLICK_AT.value,\n               lambda s, p: uia_call(lambda: vision.click_at(\n                   int(p[\"x\"]), int(p[\"y\"]), window=p.get(\"window\"),\n                   relative=bool(p.get(\"relative\")),\n                   right=bool(p.get(\"right\")), double=bool(p.get(\"double\")),\n                   from_zoom=bool(p.get(\"from_zoom\")), **_click_options(p))))\n    d.register(Method.DESKTOP_FIND_CLICK.value,\n               lambda s, p: uia_call(lambda: vision.find_and_click(\n                   _scratch_png(d, _required(s), \"find\"), str(p[\"text\"]),\n                   window=p.get(\"window\"), lang=p.get(\"lang\"),\n                   nth=int(p.get(\"nth\") or 1)), timeout=180))\n\n    d.register(Method.SITE_LIST.value,\n               lambda s, p: {\"effect_state\": \"none\", \"sites\": d.sites.hosts()})\n    d.register(Method.SITE_SHOW.value,\n               lambda s, p: {\"effect_state\": \"none\",\n                             **d.sites.show(str(p[\"host\"]))})\n    d.register(Method.SITE_CHECK.value, lambda s, p: _site_check(d, p))\n    d.register(Method.SITE_ACCEPT.value,\n               lambda s, p: {\"effect_state\": \"committed\",\n                             **d.sites.accept(str(p[\"host\"]), p.get(\"page\"),\n                                              p.get(\"state\"))})\n    d.register(Method.SITE_FORGET.value,\n               lambda s, p: {\"effect_state\": \"committed\",\n                             **d.sites.forget(str(p[\"host\"]))})\n    d.register(Method.SITE_RECIPE.value,\n               lambda s, p: {\"effect_state\": \"none\",\n                             **d.sites.recipe(str(p[\"host\"]), p.get(\"name\"))})\n    d.register(Method.SITE_RECORD_START.value,\n               lambda s, p: {\"effect_state\": \"committed\",\n                             **d.sites.start_recording(str(p[\"name\"]),\n                                                       str(p.get(\"browser\")\n                                                           or \"\"))})\n    d.register(Method.SITE_RECORD_STOP.value,\n               lambda s, p: _knowing(d, {\"effect_state\": \"committed\",\n                                         **d.sites.stop_recording()}))\n    d.register(Method.SITE_REPLAY.value, lambda s, p: _site_replay(d, p, s))\n    d.register(Method.SITE_KNOW.value, lambda s, p: _site_know(d, p))\n    d.register(Method.SITE_PAGE.value,\n               lambda s, p: {\"effect_state\": \"none\", **d.sites.page_memory(\n                   d.rb.url_of(d.rb.pick_tab(p.get(\"tab_id\"))))})\n    d.register(Method.RESEARCH_SEARCH.value, lambda s, p: _research(d, p))\n    d.register(Method.RESEARCH_READ.value, lambda s, p: _research_document(d, p))\n    from .appmem import learn_app\n    d.register(Method.APP_KNOW.value, lambda s, p: learn_app(p[\"exe\"], home=d.memory_home,\n                                                         research_port=d.research))\n\n    d.register(Method.HUMAN_REQUEST_HELP.value, lambda s, p: _request_help(d, _required(s), p))\n    d.register(Method.AUDIT_TRACE.value,\n               lambda s, p: _trace(d, p))\n    d.register(Method.AUDIT_TAIL.value,\n               lambda s, p: {\"entries\": d.audit.tail(int(p.get(\"count\", 50)),\n                                                     p.get(\"session\"))})\n\n\n# --- system ------------------------------------------------------------------\n\ndef _shutdown(d: \"Daemon\") -> dict[str, Any]:\n    d.shutdown()\n    return {\"shutting_down\": True}\n\n\ndef _run_state(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Everything the dashboard shows, in one read (polled; not audited).\"\"\"\n    from .watchdog import read_state\n    if p.get(\"wait\"):\n        d.run_control.wait_for(int(p.get(\"since\") or 0), float(p[\"wait\"]))\n    feed = d.run_control.feed(int(p.get(\"since\") or 0), int(p.get(\"limit\") or 200))\n    pending = [{k: c.get(k) for k in (\"token\", \"method\", \"detail\", \"asked_at\", \"expires_in\")}\n               for c in d.confirmations.pending()]\n    # db1: the agents and their sessions, for the dashboard's strands.\n    agents = [{k: info[k] for k in (\"session_id\", \"client\", \"agent\", \"created_at\", \"idle_s\", \"refs\", \"browser_attached\")}\n              for info in (s.info() for s in list(d.sessions.values()))]\n    return {\"effect_state\": \"none\", **d.run_control.snapshot(), \"feed\": feed[\"rows\"],\n            \"pending\": pending, \"sessions\": len(d.sessions), \"agents\": agents,\n            \"permission_mode\": d.policy.mode.value,\n            \"quiet\": not bool(getattr(d.policy, \"steal_focus\", False)),\n            \"watchdog\": read_state(d.home), \"daemon_pid\": os.getpid(),\n            \"recording\": d.human_recorder.state()}    # db8: the Record button's face; never raises\n\n\ndef _run_flow_register(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"A flow run started from a terminal (`auto flow run`) makes itself known,\n    so Stop tells it to wind up and Reset ends it, like a background run.\"\"\"\n    d.run_control.add_flow(int(p[\"pid\"]), str(p.get(\"profile\") or \"\"), str(p.get(\"log\") or \"\"),\n                           str(p.get(\"journal\") or \"\"), str(p.get(\"file\") or \"\"))\n    return {\"effect_state\": \"none\", \"registered\": int(p[\"pid\"])}\n\n\ndef _run_progress(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"A flow process reports a finished repetition (cli.py `flow run --repeat`).\"\"\"\n    d.run_control.repeat_progress(str(p.get(\"name\") or \"\"), int(p.get(\"done\") or 0),\n                                  int(p.get(\"total\") or 1))\n    return {\"effect_state\": \"none\"}\n\n\ndef _run_import(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    from . import flowfiles\n    out = flowfiles.import_file(d, Path(str(p[\"file\"])))\n    d.run_control.load_imported(flowfiles.stored_at(out))         # db7 Item F: on the map, and Clean takes it back\n    d.run_control.note(\"file\", action=\"import\", name=out.get(\"name\"), flow_kind=out.get(\"imported\"))\n    return out\n\n\ndef _run_use(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"db7 Item H: Use in the list behind Play - the saved workflow goes on the dashboard's map; Play then runs it.\"\"\"\n    found = savedpaths.find(d.sites, str(p.get(\"name\") or \"\"), site=p.get(\"site\") or None, home=d.home)\n    d.run_control.put_on_map(str(found.get(\"kind\")), found.get(\"name\"))\n    d.run_control.note(\"file\", action=\"use\", name=found.get(\"name\"), flow_kind=found.get(\"kind\"))\n    return {\"effect_state\": \"committed\", \"name\": found.get(\"name\"), \"kind\": found.get(\"kind\")}\n\n\ndef _run_forget_path(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"db7 Item H (owner order): Delete in the list behind Play removes the saved workflow from the tool's memory\n    permanently - its saved file, or the recipe from its site.\"\"\"\n    from .workflow import profiles_dir\n    found = savedpaths.find(d.sites, str(p.get(\"name\") or \"\"), site=p.get(\"site\") or None, home=d.home)\n    kind, name = str(found.get(\"kind\")), str(found.get(\"name\"))\n    if kind == \"recipe\":\n        gone = d.sites.remove_recipe(str(found.get(\"site\") or \"\"), name)\n    else:\n        target = Path(str(found.get(\"file\") or \"\"))\n        if kind == \"profile\" and not target.is_absolute():\n            target = profiles_dir() / target\n        gone = bool(found.get(\"file\")) and target.is_file()\n        if gone:\n            target.unlink()\n    d.run_control.forget_saved(name)\n    d.run_control.note(\"file\", action=\"delete\", name=name, flow_kind=kind)\n    return {\"effect_state\": \"committed\" if gone else \"none\", \"name\": name, \"kind\": kind, \"deleted\": gone}\n\n\ndef _run_clean(d: \"Daemon\") -> dict[str, Any]:\n    \"\"\"The dashboard's Clean (and its old name Reset): leftover activity ends and the view returns to ready; every\n    flow imported since the last Clean leaves the tool's memory with its name. A refused Clean removes nothing.\"\"\"\n    from . import flowfiles\n    imported = list(d.run_control.imported)\n    out = d.run_control.clean(daemon=d)\n    out[\"removed_imports\"] = flowfiles.forget_imports(d, imported)\n    return out\n\n\ndef _run_save(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Save the run: by `name` into the tool's own memory (db1, the dashboard's\n    Save), or to a `file` the owner chose (a flow file).\"\"\"\n    from . import flowfiles\n    if p.get(\"name\"):\n        out = flowfiles.save_to_memory(d, str(p[\"name\"]))\n    else:\n        out = flowfiles.save(d, Path(str(p[\"file\"])))\n    d.run_control.note(\"file\", action=\"save\", name=out.get(\"name\"), flow_kind=out.get(\"kind\"))\n    return out\n\n\ndef _run_turns(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"A run's recorded steps (db2: the dashboard's steps panel and the studio).\"\"\"\n    from .trajectory import read_run_turns, run_dir, turn_dirs\n    run_id = str(p.get(\"run_id\") or \"\")\n    last = int(p[\"last\"]) if p.get(\"last\") is not None else None\n    turns = read_run_turns(d.home, run_id, last)\n    # t5f F8: the panel reads its last rows only; total says how many the run holds\n    return {\"effect_state\": \"none\", \"run_id\": run_id, \"turns\": turns, \"total\": len(turn_dirs(run_dir(d.home, run_id)))}\n\n\ndef _run_workflow_put(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"The studio's Save: a saved run written back under its name (db2).\"\"\"\n    from .trajectory import save_workflow\n    out = save_workflow(d.home, str(p.get(\"name\") or \"\"), p.get(\"doc\"))\n    d.run_control.note(\"file\", action=\"save\", name=out.get(\"name\"), flow_kind=\"run\")\n    return out\n\n\ndef _run_workflow_file(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"db7 (owner choice 2026-10-31): the studio's Save, written to the file the owner picked in a folder.\"\"\"\n    from .trajectory import save_workflow_file\n    out = save_workflow_file(str(p.get(\"file\") or \"\"), str(p.get(\"name\") or \"\"), p.get(\"doc\"))\n    d.run_control.note(\"file\", action=\"save\", name=out.get(\"name\"), flow_kind=\"run\")\n    return out\n\n\ndef _run_agents(d: \"Daemon\") -> dict[str, Any]:\n    from . import agents_cli\n    return {\"effect_state\": \"none\", \"agents\": agents_cli.available(d.home)}    # db6: with every agent ever seen here\n\n\ndef _run_agent_api(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"db6 Item 4b (owner order 2026-10-31): the studio adds an API for any model; it is listed like an agent CLI.\"\"\"\n    from . import agents_cli, agentsmem\n    entry = agentsmem.add_api(d.home, str(p.get(\"name\") or \"\"), str(p.get(\"format\") or \"\"),\n                              str(p.get(\"base_url\") or \"\"), str(p.get(\"model\") or \"\"), str(p.get(\"key\") or \"\"),\n                              headers=str(p.get(\"headers\") or \"\"), body=str(p.get(\"body\") or \"\"),     # db7: a custom API\n                              answer=str(p.get(\"answer\") or \"\"))\n    d.__dict__.get(\"_agent_status\", {}).pop((entry[\"cli\"], entry[\"models\"][0]), None)   # db7: re-added -> check again\n    return {\"effect_state\": \"committed\", \"added\": entry, \"agents\": agents_cli.available(d.home)}\n\n\ndef _run_tool_help(p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"db7 Item B (owner order 2026-10-31): the node settings in plain words - each used tool's description and its\n    arguments' help, types, choices and required names, from the tool reference.\"\"\"\n    from . import toolspec\n    wanted = {str(m) for m in p.get(\"tools\") or []}\n    out = {}\n    for spec in toolspec.TOOLS:\n        if spec[\"method\"] not in wanted:\n            continue\n        props = spec[\"schema\"].get(\"properties\") or {}\n        out[spec[\"method\"]] = {\n            \"name\": spec[\"name\"], \"description\": spec[\"description\"], \"required\": spec[\"schema\"].get(\"required\") or [],\n            \"properties\": {k: {f: v[f] for f in (\"description\", \"type\", \"enum\", \"minimum\", \"maximum\", \"default\") if f in v}\n                           for k, v in props.items()}}\n    return {\"effect_state\": \"none\", \"help\": out}\n\n\ndef _run_find_target(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"db7 Phase 1 (owner order 2026-10-31: node editing like Power Automate / UiPath): the open windows, the elements\n    of one window (Choose from the window), or a step's elements found again exactly as replay finds them (Check on\n    screen). The handlers are called directly with a session of its own that is never registered: nothing is\n    recorded, no run starts, the feed and the history stay as they are.\"\"\"\n    import re\n    from . import trajectory\n    own = d.scratch_session()\n\n    def call(method: str, args: dict[str, Any]) -> dict[str, Any]:\n        return d._handlers[method](own, dict(args))\n    if isinstance(p.get(\"turn\"), dict):\n        turn = p[\"turn\"]\n        if not any(isinstance(v, dict) for v in (turn.get(\"target\") or {}).values()):\n            return {\"effect_state\": \"none\", \"found\": None, \"message\": \"this step names no element or window to find\"}\n        try:\n            return {\"effect_state\": \"none\", \"found\": True, \"arguments\": trajectory.resolve_arguments(call, turn)}\n        except ProtocolError as exc:            # the owner reads it in the studio: no terminal commands in the hint\n            hint = \"Open that window first, then check again.\" if exc.error.code == ErrorCode.WINDOW_NOT_FOUND else exc.error.hint\n            return {\"effect_state\": \"none\", \"found\": False, \"error\": exc.error.message, \"hint\": hint}\n    if p.get(\"window\"):\n        text = str(call(\"desktop.observe\", {\"window\": str(p[\"window\"]), \"query\": str(p.get(\"query\") or \"\"),\n                                            \"screenshot\": False}).get(\"text\") or \"\")\n        seen, elements = set(), []\n        for role, name in re.findall(r'@e\\d+ (\\S+) \"((?:[^\"\\\\]|\\\\.)*)\"', text):\n            if name and (role, name) not in seen:\n                seen.add((role, name))\n                elements.append({\"role\": role, \"name\": name})\n        return {\"effect_state\": \"none\", \"window\": str(p[\"window\"]), \"elements\": elements[:300]}\n    wins = call(\"desktop.windows\", {}).get(\"windows\") or []\n    # the handle lets the studio read exactly this window when several titles contain the same words (found on the\n    # Final Product: the \"Kgrow.io\" dashboard and \"Kgrow.io Catalog - Arabic.pdf\")\n    return {\"effect_state\": \"none\",\n            \"windows\": [{\"title\": str(w[\"title\"]), \"process\": str(w.get(\"process\") or \"\"),\n                         **({\"handle\": f\"#{w['handle']}\"} if w.get(\"handle\") else {})} for w in wins if w.get(\"title\")]}\n\n\nSTATUS_KEEP_S = 600          # db7: an agent's on/off result is reused for 10 minutes unless the owner checks again\n\n\ndef _run_agent_status(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"db7 (owner order 2026-10-31): is this agent or API on? The answer of one tiny real call, kept for a while; an\n    off agent carries its reason and the terminal commands that turn it on.\"\"\"\n    import shutil\n    import time as _time\n    from . import agents_cli, agentsmem\n    cli, model = str(p.get(\"cli\") or \"offline\"), str(p.get(\"model\") or \"default\")\n    kept = d.__dict__.setdefault(\"_agent_status\", {})\n    hit = kept.get((cli, model))\n    if hit and not p.get(\"refresh\") and _time.time() - hit[\"checked_at\"] < STATUS_KEEP_S:\n        return {**hit, \"kept\": True}\n    api = agentsmem.api(d.home, cli) if cli.startswith(\"api:\") else None\n    state = agents_cli.probe(cli, model, api)\n    if state[\"active\"] and cli != \"offline\":\n        try:\n            agentsmem.used(d.home, cli, model)\n        except OSError:\n            pass\n    found = cli.startswith((\"api:\", \"offline\")) or bool(shutil.which(cli))\n    out = {\"effect_state\": \"none\", \"cli\": cli, \"model\": model, **state, \"found\": found,\n           \"steps\": [] if state[\"active\"] else agents_cli.activation(cli, found), \"checked_at\": _time.time()}\n    kept[(cli, model)] = out\n    return out\n\n\ndef _agent_ask(d: \"Daemon\", cli: str, model: str, prompt: str, timeout: int) -> dict[str, Any]:\n    \"\"\"One agent call for Test or Fix (db6): an API agent gets its saved entry; a model that answered is remembered.\"\"\"\n    from . import agents_cli, agentsmem\n    extra = {\"api\": agentsmem.api(d.home, cli)} if cli.startswith(\"api:\") else {}\n    reply = agents_cli.ask(cli, model, prompt, timeout=timeout, **extra)\n    if reply.get(\"reply\") is not None:\n        try:\n            agentsmem.used(d.home, cli, model)\n        except OSError:\n            pass\n    return reply\n\n\ndef _run_test(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"The studio's Test (db3): the offline check always; a connected agent's review when the owner chose one.\"\"\"\n    from . import agents_cli, workflowcheck\n    agent = p.get(\"agent\") if isinstance(p.get(\"agent\"), dict) else {}\n    cli = str(agent.get(\"cli\") or \"offline\")\n    model = str(agent.get(\"model\") or \"default\")\n    turn = int(p[\"turn\"]) if p.get(\"turn\") else None\n    whole = bool(p.get(\"whole\"))          # db7: after an edit a step's Test and Fix cover the whole workflow\n    if p.get(\"repair\"):\n        return _studio_log(d, _run_repair(d, cli, model, None if whole else turn, p, focus=turn if whole else None))\n    if \"text\" in p:\n        doc, out = workflowcheck.check_text(str(p.get(\"text\") or \"\"))\n        if doc is None and cli != \"offline\" and out[\"findings\"]:        # broken JSON: the agent repairs it\n            reply = _agent_ask(d, cli, model, workflowcheck.repair_prompt(str(p.get(\"text\") or \"\"),\n                                                                        out[\"findings\"][0][\"message\"]),\n                               int(p.get(\"timeout\") or agents_cli.DEFAULT_TIMEOUT))\n            fixed = (reply.get(\"reply\") or {}).get(\"fixed_doc\")\n            if isinstance(fixed, dict):\n                out[\"findings\"][0][\"fixed_doc\"] = fixed\n                out[\"findings\"][0][\"by\"] = cli\n            else:\n                out[\"agent_error\"] = f\"{cli} gave no corrected document\" + (f\" ({reply['error']})\" if reply.get(\"error\") else \"\")\n            out[\"command\"] = reply.get(\"command\")\n    else:\n        doc = p.get(\"doc\")\n        out = workflowcheck.check_doc(doc)\n    if turn and not whole:\n        out[\"findings\"] = [f for f in out[\"findings\"] if f.get(\"turn\") in (None, turn)]\n    result: dict[str, Any] = {\"effect_state\": \"none\", \"agent\": cli, \"model\": model, **out}\n    if whole and turn:\n        result[\"focus\"] = turn\n    if cli != \"offline\" and isinstance(doc, dict) and doc.get(\"kind\") == \"run\":\n        reply = _agent_ask(d, cli, model, workflowcheck.agent_prompt(doc, None if whole else turn,\n                                                                    focus=turn if whole else None),\n                           int(p.get(\"timeout\") or agents_cli.DEFAULT_TIMEOUT))\n        result[\"command\"] = reply.get(\"command\")\n        result[\"elapsed_ms\"] = reply.get(\"elapsed_ms\")\n        if reply.get(\"reply\") is None:\n            result[\"agent_error\"] = (f\"{cli} gave no JSON answer\"\n                                     + (f\" ({reply['error']})\" if reply.get(\"error\") else \"\")\n                                     + (f\": {reply['output'][-400:]}\" if reply.get(\"output\") else \"\"))\n        else:\n            result[\"findings\"] = result[\"findings\"] + workflowcheck.agent_findings(reply[\"reply\"], cli,\n                                                                                   None if whole else turn)\n            if isinstance(reply[\"reply\"].get(\"purpose\"), str):\n                result[\"purpose\"] = reply[\"reply\"][\"purpose\"]         # db7: what the agent understood the workflow does\n    result[\"ok\"] = not any(f.get(\"severity\") == \"error\" for f in result[\"findings\"])\n    return _studio_log(d, result)\n\n\ndef _studio_log(d: \"Daemon\", result: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"db7 Item J: every Test and Fix result is kept in <home>/studio-tests.jsonl - the owner's Fix test left no\n    record of what the agents answered. Never fails the press.\"\"\"\n    import json\n    fixed = ([t.get(\"turn\") for t in result.get(\"fixed_turns\") or []]\n             + ([result[\"fixed_turn\"].get(\"turn\")] if result.get(\"fixed_turn\") else [])\n             + ([\"document\"] if result.get(\"fixed_doc\") else []))\n    row = {\"at\": time.strftime(\"%Y-%m-%dT%H:%M:%S%z\"), \"agent\": result.get(\"agent\"), \"model\": result.get(\"model\"),\n           \"repair\": bool(result.get(\"repair\")), \"ok\": result.get(\"ok\"), \"fixed\": fixed,\n           \"findings\": [{\"turn\": f.get(\"turn\"), \"severity\": f.get(\"severity\"), \"by\": f.get(\"by\"),\n                         \"message\": str(f.get(\"message\") or \"\")[:200]} for f in result.get(\"findings\") or []],\n           \"agent_error\": result.get(\"agent_error\"), \"elapsed_ms\": result.get(\"elapsed_ms\")}\n    try:\n        with open(d.home / \"studio-tests.jsonl\", \"a\", encoding=\"utf-8\") as fh:\n            fh.write(json.dumps(row, ensure_ascii=False, default=str) + \"\\n\")\n    except OSError:\n        pass\n    return result\n\n\ndef _run_repair(d: \"Daemon\", cli: str, model: str, turn: int | None, p: dict[str, Any],\n                focus: int | None = None) -> dict[str, Any]:\n    \"\"\"db6 (owner order 2026-10-31): the studio's Fix when the Test returned no ready fix - the chosen agent writes\n    the corrected step (`turn`) or the corrected document (the whole workflow, or the code window's text).\"\"\"\n    from . import agents_cli, workflowcheck\n    if cli == \"offline\":\n        raise ProtocolError(ErrorCode.UNSUPPORTED, \"the offline check finds problems but cannot write a fix\",\n                            hint=\"Choose a connected agent and press Fix again.\")\n    findings = [f for f in p.get(\"findings\") or [] if isinstance(f, dict)]\n    if \"text\" in p:                       # the code window: a step's code (turn given) or the whole document\n        subject: Any = str(p.get(\"text\") or \"\")\n    else:\n        doc = p.get(\"doc\")\n        if not isinstance(doc, dict):\n            raise ValueError(\"Fix needs the workflow (doc) or the code text\")\n        subject = doc\n        if turn:\n            subject = next((t for t in doc.get(\"turns\") or [] if isinstance(t, dict) and t.get(\"turn\") == turn), None)\n            if subject is None:\n                raise ValueError(f\"step {turn} is not in the workflow\")\n    reply = _agent_ask(d, cli, model, workflowcheck.fix_prompt(subject, findings, turn, focus=focus),\n                       int(p.get(\"timeout\") or agents_cli.DEFAULT_TIMEOUT))\n    out: dict[str, Any] = {\"effect_state\": \"none\", \"agent\": cli, \"model\": model, \"repair\": True,\n                           \"command\": reply.get(\"command\"), \"elapsed_ms\": reply.get(\"elapsed_ms\")}\n    key = \"fixed_turn\" if turn else \"fixed_doc\"\n    answer = reply.get(\"reply\") if isinstance(reply.get(\"reply\"), dict) else {}\n    if isinstance(answer.get(\"purpose\"), str):\n        out[\"purpose\"] = answer[\"purpose\"]\n    fixed = answer.get(key)\n    usable = isinstance(fixed, dict) and (bool(fixed.get(\"tool\")) if turn else isinstance(fixed.get(\"turns\"), list))\n    # db7 Item J: a whole workflow's Fix may answer only the changed steps, each kept by its own step number\n    numbers = {t.get(\"turn\") for t in subject.get(\"turns\") or [] if isinstance(t, dict)} if isinstance(subject, dict) else set()\n    changed = [t for t in answer.get(\"fixed_turns\") or [] if isinstance(t, dict) and t.get(\"tool\") and t.get(\"turn\") in numbers]\n    if usable:\n        out[key] = {**fixed, \"turn\": turn} if turn else fixed\n        out[\"by\"] = cli\n    elif not turn and changed:\n        out[\"fixed_turns\"] = changed\n        out[\"by\"] = cli\n    else:\n        out[\"agent_error\"] = (f\"{cli} gave no corrected {'step' if turn else 'document'}\"\n                              + (f\" ({reply['error']})\" if reply.get(\"error\") else \"\")\n                              + (f\": {reply['output'][-400:]}\" if reply.get(\"output\") and not answer else \"\"))\n    return out\n\n\ndef _dashboard_checks(d: \"Daemon\") -> list[tuple[str, bool, str, str]]:\n    \"\"\"The Kgrow.io dashboard in `auto doctor` (DB-07).\"\"\"\n    from .dashboard import launch\n    from .dashboard.server import STATIC\n    missing = [f for f in (\"index.html\", \"app.js\", \"style.css\", \"kgrow.ico\", \"studio.html\", \"studio.js\", \"studio.css\")\n               if not (STATIC / f).is_file()]\n    browser = launch.browser()\n    running = launch.running(d.home)\n    snap = d.run_control.snapshot()\n    return [\n        (\"Kgrow.io dashboard page\", not missing, \"all files present\" if not missing else\n         \"missing: \" + \", \".join(missing), \"Restore src/autoskill/dashboard/static from the project.\"),\n        (\"Kgrow.io dashboard window\", bool(browser), browser or \"no Edge or Chrome found\",\n         \"Install Edge or Chrome; without one the dashboard opens in the default browser.\"),\n        (\"Kgrow.io run control\", True,\n         f\"{snap['state']}\" + (f\", run: {snap['run']['kind']}\" if snap.get(\"run\") else \", no run\")\n         + f\", repeat {snap['repeat']}, dashboard \" + (\"open\" if running else \"closed\"), \"\"),\n    ]\n\n\ndef _confirm_answer(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    token = str(p.get(\"token\") or \"\")\n    granted = bool(p.get(\"granted\"))\n    if not d.confirmations.answer(token, granted):\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED, f\"no pending approval with token {token!r}\",\n            hint=\"It may have expired. Run `auto status` to see pending ones.\")\n    # Answered outside the dashboard (`auto approve` / `auto deny`): the\n    # dashboard's log shows it like a button press (DB-07).\n    d.run_control.note(\"approval\", scope=\"once\" if granted else \"deny\", answered=1, via=\"terminal\")\n    return {\"token\": token, \"granted\": granted, \"effect_state\": \"none\"}\n\n\ndef _config_set(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Refused by design.\n\n    Changing the permission mode over RPC would let the agent widen its own\n    authority, which defeats the entire point of having modes. The mode is\n    changed by whoever holds the shell, via `auto config set`, which writes the\n    policy file directly.\n    \"\"\"\n    raise ProtocolError(\n        ErrorCode.PERMISSION_DENIED,\n        \"the permission mode cannot be changed through the daemon\",\n        hint=\"This is deliberate: an agent must not be able to widen its own \"\n             \"permissions. The user changes it with `auto config set \"\n             \"permission-mode <strict|guarded|full>`.\")\n\n\n# --- saved paths ---------------------------------------------------------------\n\ndef _run_record(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"db8 (the db6 Item 5 owner order): the dashboard's Record button - start or stop recording the owner's own\n    actions (clicks, keys, the time of each action, applications launched, commands typed into cmd or PowerShell).\n    The recording becomes a run like any agent run, so Export, Save, Import and Play work unchanged.\"\"\"\n    state = str(p.get(\"state\") or \"\")\n    if state == \"start\":\n        return d.human_recorder.start()\n    if state == \"stop\":\n        return d.human_recorder.stop()\n    raise ProtocolError(ErrorCode.UNSUPPORTED, f\"not a recording state: {state!r}\",\n                        hint='The button sends {\"state\": \"start\"} or {\"state\": \"stop\"}.')\n\n\ndef _run_play(d: \"Daemon\") -> dict[str, Any]:\n    \"\"\"db6 (owner order 2026-10-31): the dashboard's Play - once the workflow has ended, run it again: a saved path by\n    its name (the saved version, with the studio's edits), any other run from its own recorded steps. The replay runs\n    in the background like a path.run, so the page answers at once and its feed shows the steps.\"\"\"\n    import threading\n    from . import trajectory\n    snap = d.run_control.snapshot()\n    if snap[\"state\"] == \"stopped\":\n        raise ProtocolError(ErrorCode.UNSUPPORTED, \"the tool is stopped\", hint=\"Press Resume first, then Play.\")\n    if snap[\"run\"]:\n        raise ProtocolError(ErrorCode.UNSUPPORTED, \"a workflow is running now\",\n                            hint=\"Play runs the workflow again once it has ended.\")\n    last = snap[\"last_run\"]\n    if not last:\n        raise ProtocolError(ErrorCode.UNSUPPORTED, \"nothing has run yet: there is no workflow to play\",\n                            hint=\"Run or record a workflow first.\")\n    name = str(last.get(\"name\") or \"\")\n    saved = None\n    if name and last.get(\"kind\") in (\"run\", \"profile\", \"recipe\"):\n        try:\n            saved = savedpaths.find(d.sites, name, home=d.home)\n        except ProtocolError:\n            saved = None\n    if saved is not None:\n        playing = name\n\n        def target() -> None:\n            _path_run(d, None, {\"name\": name})\n    else:\n        playing = str(last.get(\"run_id\") or \"\")\n        turns = trajectory.read_run_turns(d.home, playing) if playing else []\n        if not any(not t.get(\"read_only\") for t in turns):\n            raise ProtocolError(ErrorCode.UNSUPPORTED, \"the last run has no step to play\",\n                                hint=\"Only its reads were recorded; nothing would happen.\")\n\n        def target() -> None:\n            d.run_control.begin(\"run\", playing)\n            d.run_control.open_dashboard(\"path\")\n            _replay_run(d, None, {\"turns\": turns}, {\"kind\": \"run\", \"name\": playing},\n                        int(d.run_control.repeat or 1))\n    d.run_control.note(\"control\", action=\"play\", name=playing)\n\n    def background() -> None:\n        try:\n            target()\n        except Exception as exc:                # noqa: BLE001 - the feed shows why the replay ended\n            d.run_control.note(\"run\", action=\"end\", name=playing, error=str(exc)[:300])\n    threading.Thread(target=background, daemon=True, name=\"kgrow-play\").start()\n    return {\"effect_state\": \"committed\", \"playing\": playing}\n\n\ndef _path_run(d: \"Daemon\", s: \"Session | None\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Run a saved path named exactly; the owning method (site.replay or\n    flow.start) runs it through the daemon, with its own permission check.\"\"\"\n    # Repeat: the caller's number, else the owner's setting in the dashboard\n    # (runcontrol.py). A saved path never carries it (flowfiles.py).\n    # db4: a path.run inside a running path.run (a saved run calling a saved path) is one step of that run:\n    # it runs once unless the step itself says repeat, keeps the outer run's record and its progress.\n    nested = getattr(d, \"path_depth\", 0) > 0\n    d.path_depth = getattr(d, \"path_depth\", 0) + 1\n    try:\n        return _path_run_inner(d, s, p, nested)\n    finally:\n        d.path_depth -= 1\n\n\ndef _path_run_inner(d: \"Daemon\", s: \"Session | None\", p: dict[str, Any], nested: bool) -> dict[str, Any]:\n    from .protocol import Request\n    method, params, found = savedpaths.run_request(d.sites, p, home=d.home)\n    total = int(p.get(\"repeat\") or (1 if nested else d.run_control.repeat) or 1)\n    if not 1 <= total <= 999:\n        raise ProtocolError(ErrorCode.UNSUPPORTED, f\"repeat must be 1 to 999, not {total}\")\n    if not nested:\n        d.run_control.begin(found[\"kind\"], found[\"name\"], site=found.get(\"site\"),\n                            session=s.id if s else None)\n        d.run_control.open_dashboard(\"path\")\n    if method == \"flow.start\":\n        # The queue runs in its own process, which repeats itself and reports\n        # each finished repetition (cli.py `flow run --repeat`).\n        params[\"repeat\"] = total\n        if not nested:\n            d.run_control.repeat_progress(found[\"name\"], 0, total)\n        return {**_delegate(d, s, method, params), \"saved_path\": found, \"repeat\": total}\n    if method == savedpaths.REPLAY:\n        return _replay_run(d, s, params, found, total, report=not nested)\n    result: dict[str, Any] = {}\n    if not nested:\n        d.run_control.repeat_progress(found[\"name\"], 0, total)\n    for done in range(total):\n        if d.run_control.stopped():\n            return {**result, \"saved_path\": found, \"repeat\": total, \"repetitions_done\": done,\n                    \"stopped\": \"the owner pressed Stop\"}\n        try:\n            result = _delegate(d, s, method, params)\n        except ProtocolError as exc:\n            if total > 1:\n                exc.error.message = f\"repetition {done + 1} of {total}: {exc.error.message}\"\n                exc.error.details = {**(exc.error.details or {}), \"repetitions_done\": done}\n            raise\n        if not nested:\n            d.run_control.repeat_progress(found[\"name\"], done + 1, total)\n    return {**result, \"saved_path\": found, \"repeat\": total, \"repetitions_done\": total}\n\n\ndef _replay_run(d: \"Daemon\", s: \"Session | None\", params: dict[str, Any], found: dict[str, Any],\n                total: int, report: bool = True) -> dict[str, Any]:\n    \"\"\"A saved run (a recorded trajectory) replayed the way CUA's\n    replay_trajectory does: every recorded step sent through the daemon again,\n    in order, with the caller's session or one of its own (trajectory.py).\"\"\"\n    from . import trajectory\n    turns = list(params.get(\"turns\") or [])\n    own = s is None\n    session = s or d.new_session(client={\"name\": \"path.run\", \"pid\": os.getpid()})\n    result: dict[str, Any] = {}\n    if report:\n        d.run_control.repeat_progress(found[\"name\"], 0, total)\n    try:\n        for done in range(total):\n            if d.run_control.stopped():\n                return {**result, \"saved_path\": found, \"repeat\": total, \"repetitions_done\": done,\n                        \"stopped\": \"the owner pressed Stop\"}\n            result = trajectory.replay(\n                lambda method, args: _delegate(d, session, method, args), turns,\n                delay_ms=int(params.get(\"delay_ms\") or trajectory.DEFAULT_DELAY_MS),\n                stop_on_error=bool(params.get(\"stop_on_error\", True)),\n                include_reads=bool(params.get(\"include_reads\")), stopped=d.run_control.stopped,\n                repetition=done + 1, repetitions=total)\n            if result.get(\"first_failure\") and params.get(\"stop_on_error\", True):\n                failure = result[\"first_failure\"]\n                message = f\"step {failure['turn']} ({failure['tool']}): {failure['error']}\"\n                if total > 1:\n                    message = f\"repetition {done + 1} of {total}: {message}\"\n                exc = ProtocolError(ErrorCode.TARGET_NOT_FOUND, message,\n                                    hint=\"The replay stopped at the first failed step; nothing after it ran.\",\n                                    effect_state=EffectState.UNKNOWN if result.get(\"succeeded\") else EffectState.NONE)\n                exc.error.details = {**result, \"repetitions_done\": done}\n                raise exc\n            if result.get(\"stopped\"):\n                return {**result, \"saved_path\": found, \"repeat\": total, \"repetitions_done\": done}\n            if report:\n                d.run_control.repeat_progress(found[\"name\"], done + 1, total)\n        return {\"effect_state\": \"committed\" if result.get(\"succeeded\") else \"none\", **result,\n                \"saved_path\": found, \"repeat\": total, \"repetitions_done\": total}\n    finally:\n        if own:\n            try:\n                d.stop_session(session.id)\n            except ProtocolError:\n                pass\n            d.run_control.end_if_idle(len(d.sessions))\n\n\ndef _delegate(d: \"Daemon\", s: \"Session | None\", method: str, params: dict[str, Any]) -> dict[str, Any]:\n    from .protocol import Request\n    response = d.handle(Request(method=method, params=dict(params), session=s.id if s else None))\n    if not response.ok:\n        error = response.error or {\"code\": \"internal\", \"message\": \"missing error\"}\n        exc = ProtocolError(ErrorCode(error[\"code\"]), error[\"message\"], hint=error.get(\"hint\"),\n                            effect_state=EffectState(error.get(\"effect_state\", \"none\")))\n        exc.error.details = error.get(\"details\")\n        raise exc\n    return response.result or {}\n\n\n# --- sessions ----------------------------------------------------------------\n\ndef _cua_lifecycle(method: str, params: dict[str, Any]) -> dict[str, Any]:\n    from .desktop import driver_backend\n    reply = driver_backend.try_call(method, params)\n    if reply is None:\n        return {\"cua_session\": \"unavailable\"}\n    if not reply.get(\"ok\"):\n        return {\"cua_error\": dict(reply.get(\"error\") or {\n            \"code\": \"driver_error\", \"message\": \"missing error\", \"effect_state\": \"unknown\"})}\n    return {\"cua_session\": dict(reply.get(\"result\") or {})}\n\n\ndef _session_start(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    client = p.get(\"client\") if isinstance(p.get(\"client\"), dict) else None\n    s = d.new_session(memory=p.get(\"memory\") or None, new_memory=p.get(\"new_memory\") or None, client=client)\n    out = {\"session_id\": s.id,\n           \"permission_mode\": d.policy.mode.value,\n           \"memory_space\": s.memory_space,\n           \"created_at\": s.created_at,\n           \"client\": dict(s.client)}\n    out.update(_cua_lifecycle(\"session_start\", {\"session\": s.id}))\n    # db7 Item H (owner): when an agent starts working, the dashboard's Desktop shortcut is looked for by its name and\n    # made when missing (the owner's own home only - Daemon._ensure_desktop_shortcut)\n    import threading\n    threading.Thread(target=d._ensure_desktop_shortcut, daemon=True, name=\"kgrow-shortcut\").start()\n    return out\n\n\ndef _session_stop(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    sid = p.get(\"session_id\") or p.get(\"id\")\n    if not sid:\n        raise ProtocolError(ErrorCode.NO_SESSION, \"session id is required\")\n    return d.stop_session(str(sid))\n\n\ndef _session_list(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    limit = int(p.get(\"limit\", 100))\n    if not 1 <= limit <= 100:\n        raise ProtocolError(ErrorCode.UNSUPPORTED, \"session_list.limit must be from 1 to 100\")\n    cursor = p.get(\"cursor\")\n    if cursor is not None and (not isinstance(cursor, str)\n                               or not cursor.startswith(\"o:\")\n                               or not cursor[2:].isdigit()):\n        raise ProtocolError(ErrorCode.UNSUPPORTED, \"session_list.cursor is invalid\")\n    offset = int(cursor[2:]) if cursor else 0\n    params: dict[str, Any] = {\"limit\": limit}\n    if cursor is not None:\n        params[\"cursor\"] = cursor\n    rows = [x.info() for x in d.sessions.values()]\n    out: dict[str, Any] = {\"sessions\": rows[offset:offset + limit]}\n    if offset + limit < len(rows):\n        out[\"next_cursor\"] = f\"o:{offset + limit}\"\n    out.update(_cua_lifecycle(\"session_list\", params))\n    lifecycle = out.get(\"cua_session\")\n    if isinstance(lifecycle, dict):\n        by_id = {row.get(\"session\"): row for row in lifecycle.get(\"sessions\", [])\n                 if isinstance(row, dict)}\n        for row in out[\"sessions\"]:\n            found = by_id.get(row[\"session_id\"])\n            if found is not None:\n                row[\"cua_session\"] = found\n    return out\n\n\n# --- desktop -----------------------------------------------------------------\n\ndef _windows(p: dict[str, Any]) -> dict[str, Any]:\n    wins = actions.list_windows(include_hidden=bool(p.get(\"all\")))\n    return {\"windows\": wins, \"count\": len(wins), \"effect_state\": \"none\"}\n\n\ndef _resolve_window(p: dict[str, Any], s: \"Session\") -> Any:\n    \"\"\"Pick the window to observe: explicit title, else the foreground one.\"\"\"\n    title = p.get(\"window\") or p.get(\"title\")\n    if title:\n        w = actions.find_window(str(title))\n        if w is None:\n            raise ProtocolError(\n                ErrorCode.WINDOW_NOT_FOUND,\n                f\"no window whose title contains {title!r}\",\n                hint=\"Run `auto windows` to list what is open.\")\n        return w\n    try:\n        import uiautomation as ua\n        w = ua.GetForegroundControl()\n        # Walk up to the top-level window: the foreground control is often a\n        # child, and observing from a child hides the rest of the app.\n        for _ in range(12):\n            if w is None:\n                break\n            if (getattr(w, \"ControlTypeName\", \"\") == \"WindowControl\"\n                    and getattr(w, \"NativeWindowHandle\", 0)):\n                return w\n            w = w.GetParentControl()\n    except Exception:\n        pass\n    raise ProtocolError(\n        ErrorCode.WINDOW_NOT_FOUND, \"could not determine the active window\",\n        hint=\"Pass --window <title substring>, or run `auto windows` first.\")\n\n\ndef _appmem_note(d: \"Daemon\", proc: str) -> str | None:\n    \"\"\"A one-line nudge when observe/click meets an app the tool has never\n    learned (S152). Fail-open: memory trouble must never break an action.\"\"\"\n    try:\n        from . import appmem\n        if proc and not appmem.AppMemory(d.memory_home).known(proc):\n            exe = appmem.norm_exe(proc)\n            return f\"app not known yet — `auto app know {exe}` learns it\"\n    except Exception:\n        pass\n    return None\n\n\ndef _observe_target(p: dict[str, Any], s: \"Session\") -> Any:\n    \"\"\"p3r D5 (G-W06): a '#handle' observe served by the driver resolves the window through Win32 only\n    (actions._driver_window, the route the driver's action verbs use). UIA ControlFromHandle on a hung provider blocks\n    the single UIA thread - and so every desktop verb - for the whole hang; CUA's walk answers within its timeout_ms\n    budget. The Python fallback walk resolves the UIA control itself.\"\"\"\n    # shortcut: on this route `modal` is the #32770 class rule only (no UIA WindowPattern.IsModal read); upgrade with\n    # a Win32 owner-disabled check if a non-dialog modal hint is needed.\n    from .desktop import driver_backend\n    sel = str(p.get(\"window\") or p.get(\"title\") or \"\").strip()\n    if sel.startswith(\"#\") and not p.get(\"all\") and driver_backend.supports(\"window_state\"):\n        w = actions._driver_window(sel)\n        if w is not None:\n            return w\n    return _resolve_window(p, s)\n\n\ndef _observe(d: \"Daemon\", s: \"Session\", p: dict[str, Any], *,\n             reporter: PerceptionReporter | None = None) -> dict[str, Any]:\n    w = _observe_target(p, s)\n    title = getattr(w, \"Name\", \"\") or \"\"\n    proc = actions._process_name(w)\n\n    max_nodes = int(p.get(\"max_nodes\", uia.MAX_NODES))\n    max_depth = int(p.get(\"max_depth\", uia.MAX_DEPTH))\n    # b12t7 (OQ-B1 resolved to CUA's own default, impl_.rs:1257): an\n    # observe takes a grounding screenshot unless the caller sends\n    # screenshot:false (CUA's \"cheap path for re-indexing\"). The capture is\n    # stored (OQ-B5: an optional max_image_dimension rides along; when\n    # absent the adapter's 1568 pin applies).\n    screenshot = bool(p.get(\"screenshot\", True))\n    max_image_dimension = p.get(\"max_image_dimension\")\n    obs = _observe_via_driver_or_python(\n        w, s, proc=proc, title=title, include_offscreen=bool(p.get(\"all\")),\n        max_nodes=max_nodes, max_depth=max_depth,\n        screenshot=screenshot,\n        screenshot_explicit=\"screenshot\" in p,\n        max_image_dimension=(int(max_image_dimension)\n                             if max_image_dimension is not None else None),\n        query=p.get(\"query\"))\n    s.last_window = title\n    if reporter is not None:\n        reporter.report(PerceptionSummary(Component.DESKTOP, PerceptionMode.UIA,\n                         obs.ref_count, obs.node_count, obs.truncated, obs.modal))\n    out = {\"text\": uia.render(obs), **obs.to_dict(), \"effect_state\": \"none\"}\n    if screenshot and getattr(obs, \"screenshot_error\", None):\n        # CUA's own shape (impl_.rs:1772-1782): the tree plus the reason the\n        # capture is unavailable, verbatim. An older stored capture is never\n        # shown as this observe's capture.\n        out[\"screenshot_error\"] = obs.screenshot_error\n    elif screenshot:\n        from .desktop import captures\n        entry = (captures.peek(s.id, obs.window_pid, obs.top_window)\n                 if getattr(obs, \"window_pid\", None)\n                 and getattr(obs, \"top_window\", None) else None)\n        if entry:\n            # The additive capture key: visible to MCP clients (the full\n            # result dict reaches structuredContent); the CLI renderer\n            # ignores it; the dashboard never renders observe payloads.\n            out[\"capture\"] = {\n                \"capture_id\": entry.capture_id,\n                \"mime_type\": entry.mime_type,\n                \"width\": entry.width,\n                \"height\": entry.height,\n                \"image_base64\": entry.image_base64}\n    hint = _appmem_note(d, proc)\n    if hint:\n        out[\"text\"] += \"\\n\\n\" + hint\n    return out\n\n\ndef _observe_via_driver_or_python(w: Any, s: \"Session\", *, proc: str,\n                                  title: str, include_offscreen: bool,\n                                  max_nodes: int, max_depth: int,\n                                  screenshot: bool = False,\n                                  max_image_dimension: int | None = None,\n                                  screenshot_explicit: bool = True,\n                                  query: str | None = None) -> Any:\n    \"\"\"Driver-first observation; the Python walk remains the fallback.\n\n    An observation sends no input, so an unavailable or refusing driver\n    fails open to the Python walk (plan 0.3.3). The driver path uses the\n    batch-1 exact-handle resolution's identity: the control's own handle,\n    pid and title, which the SDK validates itself.\n\n    b12t2: screenshot=True additionally sends include_screenshot (plus an\n    optional max_image_dimension, OQ-B5) and stores the capture. A\n    screenshot-refusal still fails open to the Python walk — the driver\n    answer for the tree is unaffected; only the capture is unavailable.\n    \"\"\"\n    from .desktop import driver_backend\n    handle = 0\n    pid = 0\n    if not include_offscreen:\n        try:\n            handle = int(w.NativeWindowHandle or 0)\n            pid = int(w.ProcessId or 0)\n        except Exception:\n            handle = pid = 0\n    if handle and pid:\n        params: dict[str, Any] = {\n            \"pid\": pid, \"window_id\": handle,\n            \"max_elements\": min(max_nodes, 5000),\n            \"max_depth\": min(max_depth, 25)}\n        # p3h: CUA get_window_state's compacting projection (harness_wpf_test.rs:302-346).\n        # shortcut: the Python fallback walk below has no projection and returns the whole tree.\n        if query:\n            params[\"query\"] = str(query)\n        if screenshot:\n            params[\"include_screenshot\"] = True\n            if max_image_dimension is not None:\n                params[\"max_image_dimension\"] = max_image_dimension\n        # i6a: a re-observe of a window whose driver refs are live CAN\n        # ask for the delta (since:\"latest\" = this window's most recent\n        # read with the same view) - but only while DRIVER_SINCE_READS\n        # (refs.py) allows it: the pinned SDK errors its own delta output\n        # (i6a-off), so live paths send no since key at all.\n        if _refs.DRIVER_SINCE_READS and s.ref_store.holds_driver_window(\n                pid, handle):\n            params[\"since\"] = \"latest\"\n        if screenshot:\n            # b12t5 (B12-5): a CUA capture never photographs AutoSkill's\n            # own marker or dashboard; the default observe takes no image.\n            from .desktop import captures\n            with captures.hidden_capture():\n                reply = driver_backend.try_call(\"window_state\", params)\n        else:\n            reply = driver_backend.try_call(\"window_state\", params)\n        if reply is not None and not reply.get(\"ok\") and screenshot \\\n                and screenshot_explicit:\n            # b12t2: the caller explicitly opted into a capture, so a\n            # screenshot refusal surfaces VERBATIM (CUA's own code and\n            # message; no AutoSkill-made refusal) instead of silently\n            # failing open to the tree-only walk. The default observe\n            # (no opt-in) keeps today's fail-open.\n            error = reply.get(\"error\") or {}\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED,\n                f\"driver refused observe screenshot on {title or w.Name!r}: \"\n                f\"{error.get('code', 'driver_error')}: \"\n                f\"{error.get('message', '')}\",\n                effect_state=EffectState(\n                    error.get(\"effect_state\", \"none\")))\n        if reply is not None and reply.get(\"ok\"):\n            screenshot_error = None\n            if screenshot:\n                from .desktop import captures\n                shot = captures.store(reply[\"result\"], s.id, pid, handle)\n                if shot is not None:\n                    captures.remember_image(handle, shot.width, shot.height)   # fx2\n                else:\n                    # b12t6 live L8 + b12t7: CUA answers ok for a window it\n                    # cannot capture (minimized, #1973) and names the reason\n                    # in screenshot_error; it is surfaced verbatim next to\n                    # the tree (CUA's own non-failing shape).\n                    screenshot_error = reply[\"result\"].get(\"screenshot_error\") \\\n                        or \"the reply carried no capture_id\"\n            rect = None\n            r = _safe_rect(w)\n            if r:\n                rect = (r.left, r.top, r.right, r.bottom)\n            obs = uia.observe_via_driver(\n                reply[\"result\"], s.ref_store, process=proc,\n                window_title=title, window_handle=handle, window_pid=pid,\n                window_rect=rect, modal=uia.detect_modal(w), query=query)\n            # b12t2: the capture peek key — additive attrs (the\n            # Observation dataclass needs no shape change).\n            obs.window_pid = pid\n            obs.top_window = handle\n            obs.screenshot_error = screenshot_error\n            return obs\n    if getattr(w, \"win32_view\", False):  # p3r D5: the Win32 view of _observe_target; the walk needs UIA\n        w = actions.find_window(f\"#{w.NativeWindowHandle}\")\n        if w is None:\n            raise ProtocolError(ErrorCode.WINDOW_NOT_FOUND, f\"no window whose title contains {title!r}\",\n                                hint=\"Run `auto windows` to list what is open.\")\n    return uia.observe(w, s.ref_store, process=proc, window_title=title,\n                       include_offscreen=include_offscreen,\n                       max_nodes=max_nodes, max_depth=max_depth)\n\n\ndef _safe_rect(w: Any) -> Any:\n    try:\n        return w.BoundingRectangle\n    except Exception:\n        return None\n\n\ndef _click_options(p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"b5t45: CUA click's count / button / modifier keys (impl_.rs:3341-3362),\n    passed through only when given; p3h: and its delivery_mode.\"\"\"\n    mods = p.get(\"modifier\")\n    return {\"count\": int(p[\"count\"]) if p.get(\"count\") is not None else None,\n            \"button\": str(p[\"button\"]) if p.get(\"button\") else None,\n            \"modifier\": [str(m) for m in mods] if mods else None,\n            \"delivery_mode\": str(p[\"delivery_mode\"]) if p.get(\"delivery_mode\") else None}\n\n\ndef _click(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    out = actions.click(s.ref_store, p[\"ref\"], double=bool(p.get(\"double\")),\n                        right=bool(p.get(\"right\")), real=bool(p.get(\"real\")),\n                        action=str(p[\"action\"]) if p.get(\"action\") else None,  # fx3\n                        **_click_options(p))\n    proc = \"\"\n    try:\n        proc = getattr(s.ref_store.resolve(p[\"ref\"]), \"process\", \"\") or \"\"\n    except Exception:\n        pass\n    hint = _appmem_note(d, proc)\n    if hint:\n        out[\"note\"] = (str(out[\"note\"]) + \"  \" if out.get(\"note\") else \"\") + hint\n    return out\n\n\ndef _extract(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Plain text of a window, without the tree structure around it.\n\n    The browser side has audited extractors; the desktop returned only a tree,\n    which forces an agent to parse indented observation text to read a\n    document. This walks the same UIA tree but emits reading-order text.\n    \"\"\"\n    w = _resolve_window(p, s)\n    title = getattr(w, \"Name\", \"\") or \"\"\n    proc = actions._process_name(w)\n    out = uia.extract_text(w, max_chars=int(p.get(\"max_chars\", 20000)))\n    out[\"window\"] = title\n    return out\n\n\ndef _focus(s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    if p.get(\"ref\"):\n        return actions.focus(s.ref_store, str(p[\"ref\"]))\n    if p.get(\"window\"):\n        res = actions.focus_window(str(p[\"window\"]), force_fallback=bool(p.get(\"force_fallback\")))\n        s.last_window = res.get(\"title\")\n        return res\n    raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                        \"pass --ref @eN or --window <title>\")\n\n\ndef _screenshot(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    out = p.get(\"out\")\n    if out:\n        path = Path(out)\n    else:\n        # A screenshot is a picture of the user's screen: their mail, an\n        # HR record, a bank page. The shared temp directory keeps it\n        # forever and nobody empties it. The session's own scratch is\n        # removed when the session ends.\n        scratch = d.home / \"scratch\" / s.id\n        scratch.mkdir(parents=True, exist_ok=True)\n        path = scratch / f\"shot-{int(time.time())}.png\"\n    # b12t5 (owner decision OQ-B6): CUA's capture first; None keeps the\n    # Python mss/PrintWindow path (driver off/unavailable, or a target the\n    # Python path must resolve and refuse itself).\n    from .desktop import captures\n    shot = captures.screenshot_via_driver(path, store=s.ref_store,\n                                          ref=p.get(\"ref\"),\n                                          window=p.get(\"window\"),\n                                          find_window=actions.find_window,\n                                          guard=actions._guard)\n    if shot is not None:\n        return shot\n    return actions.screenshot(path, store=s.ref_store, ref=p.get(\"ref\"),\n                              window=p.get(\"window\"))\n\n\ndef _delivery(p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"p3r D6: CUA's delivery_mode reaches the verb only when the caller sent it.\"\"\"\n    return {\"delivery_mode\": str(p[\"delivery_mode\"])} if p.get(\"delivery_mode\") else {}\n\n\ndef _drag_args(p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"b11: presence/type only for desktop.drag (the b17 rule) - the form\n    gate, CUA vocabulary bounds and capture mapping live in actions.drag;\n    modifier is NEVER forwarded (CUA admits and ignores it on Windows).\"\"\"\n    out: dict[str, Any] = {}\n    for key in (\"ref\", \"to_ref\", \"window\", \"delivery_mode\"):  # p3r D6: CUA drag's delivery_mode\n        if p.get(key) is not None:\n            out[key] = p[key]\n    for key in (\"from_x\", \"from_y\", \"to_x\", \"to_y\"):\n        value = p.get(key)\n        if value is not None:\n            if isinstance(value, bool) or not isinstance(value, (int, float)):\n                raise ProtocolError(\n                    ErrorCode.UNSUPPORTED,\n                    f\"drag {key} must be a number\",\n                    effect_state=EffectState.NONE)\n            out[key] = value\n    if p.get(\"button\") is not None:\n        out[\"button\"] = p[\"button\"]\n    for key in (\"duration_ms\", \"steps\"):\n        value = p.get(key)\n        if value is not None:\n            if isinstance(value, bool) or not isinstance(value, int):\n                raise ProtocolError(\n                    ErrorCode.UNSUPPORTED,\n                    f\"drag {key} must be an integer\",\n                    effect_state=EffectState.NONE)\n            out[key] = value\n    if \"from_zoom\" in p:\n        out[\"from_zoom\"] = bool(p[\"from_zoom\"])\n    return out\n\n\ndef _zoom(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"b12t4a (task A, owner decisions OQ-B3 + D54): the zoom verb over\n    the adapter's zoom method - CUA's read_only magnification of a\n    window region, returned as a cropped JPEG.\"\"\"\n    # Required keys present + numeric ONLY (rule R10: ranges, ordering\n    # and the 500 px cap are CUA's checks; Python invents none).\n    values: dict[str, Any] = {}\n    for key in (\"window_id\", \"x1\", \"y1\", \"x2\", \"y2\"):\n        if key not in p:\n            raise ProtocolError(ErrorCode.UNSUPPORTED,\n                                f\"zoom requires {key}\",\n                                effect_state=EffectState.NONE)\n        value = p[key]\n        if isinstance(value, bool) or not isinstance(value, (int, float)):\n            raise ProtocolError(ErrorCode.UNSUPPORTED,\n                                f\"zoom {key} must be a number\",\n                                effect_state=EffectState.NONE)\n        values[key] = value\n    pid = p.get(\"pid\")\n    if pid is not None:\n        values[\"pid\"] = pid\n    from .desktop import captures, driver_backend\n    # b12t5 (B12-5): CUA's zoom takes a fresh native capture\n    # (impl_.rs:9128-9131); AutoSkill's own pixels stay out of it.\n    with captures.hidden_capture():\n        reply = driver_backend.try_call(\"zoom\", values)\n    if reply is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"driver unavailable for the zoom; nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused zoom on window {values['window_id']}: \"\n            f\"{error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            effect_state=EffectState(\n                error.get(\"effect_state\", \"none\")))\n    result = reply.get(\"result\") or {}\n    images = result.get(\"images\")\n    image = images[0] if isinstance(images, list) and images else {}\n    data = image.get(\"data_base64\") if isinstance(image, dict) else None\n    if not data:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver zoom reply on window {values['window_id']} carried \"\n            f\"no image\",\n            effect_state=EffectState.NONE)\n    raw = base64.b64decode(data)\n    captures.remember_zoom(s, int(values[\"window_id\"]),\n                           (values[\"x1\"], values[\"y1\"], values[\"x2\"], values[\"y2\"]))\n    out = p.get(\"out\")\n    if out:\n        path = Path(out)\n        path.parent.mkdir(parents=True, exist_ok=True)\n    else:\n        # The screenshot precedent's privacy default: a zoomed image is a\n        # picture of the user's screen. The session's own scratch is\n        # removed when the session ends.\n        scratch = d.home / \"scratch\" / s.id\n        scratch.mkdir(parents=True, exist_ok=True)\n        path = scratch / f\"zoom-{int(time.time())}.jpg\"\n    path.write_bytes(raw)\n    return {\"effect_state\": \"none\", \"path\": str(path),\n            \"width\": result.get(\"width\"), \"height\": result.get(\"height\"),\n            \"mime_type\": result.get(\"mime_type\"), \"bytes\": len(raw)}\n\n\ndef _invoke_menu(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"B17: CUA's invoke_menu - resolve an exact native menu path one\n    live level at a time and invoke the final item (impl_.rs:9266-9407\n    at the pin). Driver-only (like _zoom): AutoSkill has no menu-walk\n    helper, and CUA never falls back to pixels.\"\"\"\n    # Required keys present + type ONLY (rule R10: the 1..16 length,\n    # per-segment emptiness/trim and CUA's own required pid are the\n    # driver's checks; Python invents none).\n    window_id = p.get(\"window_id\")\n    if isinstance(window_id, bool) or not isinstance(window_id, int):\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"invoke_menu requires window_id (integer)\",\n                            effect_state=EffectState.NONE)\n    path = p.get(\"path\")\n    if not isinstance(path, list):\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"invoke_menu requires path (array of strings)\",\n                            effect_state=EffectState.NONE)\n    if p.get(\"pid\") is None:\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"invoke_menu requires pid\",\n                            effect_state=EffectState.NONE)\n    values: dict[str, Any] = {\"window_id\": window_id, \"path\": path,\n                              \"pid\": p[\"pid\"]}\n    from .desktop import driver_backend\n    reply = driver_backend.try_call(\"invoke_menu\", values)\n    if reply is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"driver unavailable for invoke_menu; nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused invoke_menu on window {window_id}: \"\n            f\"{error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            effect_state=EffectState(\n                error.get(\"effect_state\", \"none\")))\n    result = reply.get(\"result\") or {}\n    # CUA's success is text + ActionEffect::Unverifiable (impl_.rs:9381-\n    # 9403): the adapter answers text-only. Expose CUA's raw value\n    # additively (I7) and map the state honestly (K2c/D12): unverifiable\n    # is unknown, never committed without independent evidence.\n    raw_effect = result.get(\"effect\", \"unverifiable\")\n    # The daemon re-converts effect_state through the enum (deliver's\n    # annotate path), so return the plain value like every other\n    # handler (e.g. _zoom's \"none\") - never the enum member.\n    state = \"unknown\" if raw_effect == \"unverifiable\" else \"none\"\n    return {\"effect_state\": state,\n            \"effect\": raw_effect,\n            \"summary\": result.get(\"summary\", \"\"),\n            \"window_id\": window_id, \"via\": \"driver-invoke_menu\"}\n\n\ndef _clipboard_read(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"B19: CUA's clipboard_read - list the clipboard's available formats\n    and, only when include_text is set, return the text (clipboard.rs:94-108\n    at the pin; privacy_sensitive in CUA's own contract). Driver-only (the\n    _zoom pattern): AutoSkill has no format-listing twin. Python validates\n    NOTHING locally (R10): the schema has no required keys and a wrong-typed\n    include_text is the Rust adapter's shape gate, so every present\n    whitelisted key is forwarded exactly as given.\"\"\"\n    values: dict[str, Any] = {}\n    if \"include_text\" in p:\n        values[\"include_text\"] = p[\"include_text\"]\n    from .desktop import driver_backend\n    reply = driver_backend.try_call(\"clipboard_read\", values)\n    if reply is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"driver unavailable for clipboard_read; nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused clipboard_read: \"\n            f\"{error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            effect_state=EffectState(\n                error.get(\"effect_state\", \"none\")))\n    result = reply.get(\"result\") or {}\n    # A read changes nothing: the table_read precedent (ledger.py:134-135).\n    # CUA's structured payload passes through additively (I7) - the text,\n    # when present, is the tool's payload and stays out of every persisted\n    # surface (audit params are argument-free by construction).\n    out = dict(result)\n    out[\"effect_state\"] = \"none\"\n    out[\"via\"] = \"driver-clipboard_read\"\n    return out\n\n\ndef _clipboard_write(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"B19: CUA's clipboard_write - replace the clipboard with exactly one\n    of text / image file / file URL (clipboard.rs:129-171 at the pin;\n    CUA's RiskClass::R1 with click, so the INPUT risk class in\n    permissions.py - OD-13). Python validates NOTHING\n    locally (R10): exactly-one is CUA's OWN tool check and refuses with a\n    verbatim message after dispatch; absoluteness/existence belong to the\n    Windows backend. Caller stray keys never reach the driver.\"\"\"\n    values: dict[str, Any] = {}\n    for key in (\"text\", \"image_path\", \"file_path\"):\n        if key in p:\n            values[key] = p[key]\n    from .desktop import driver_backend\n    reply = driver_backend.try_call(\"clipboard_write\", values)\n    if reply is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"driver unavailable for clipboard_write; nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused clipboard_write: \"\n            f\"{error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            effect_state=EffectState(\n                error.get(\"effect_state\", \"none\")))\n    result = reply.get(\"result\") or {}\n    # K2c: CUA's success text says \"inspect structuredContent.types before\n    # paste\" - the advisory format read-back is never commit evidence, so\n    # the state is unknown, never committed.\n    out = dict(result)\n    out[\"effect_state\"] = \"unknown\"\n    out[\"via\"] = \"driver-clipboard_write\"\n    return out\n\n\ndef _verify_state(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"B20: CUA's verify_state - bounded multi-sample predicate verification\n    against one exact window (verification.rs:147-256, expectation.rs:210-351\n    at the pin; read_only:true, R2 bounded observation). Driver-only: the\n    stability loop, tri-state aggregate and conservative-absence rules are\n    ONE mechanism AutoSkill does not reimplement (R10). Local checks are\n    presence/type ONLY (the b17 _invoke_menu precedent): pid present,\n    window_id integer (bool excluded), expect array - the 1..8 bound,\n    ranges, exists=false and selector emptiness are CUA's own checks and\n    surface verbatim.\"\"\"\n    if p.get(\"pid\") is None:\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"verify_state requires pid\",\n                            effect_state=EffectState.NONE)\n    window_id = p.get(\"window_id\")\n    if isinstance(window_id, bool) or not isinstance(window_id, int):\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"verify_state requires window_id (integer)\",\n                            effect_state=EffectState.NONE)\n    expect = p.get(\"expect\")\n    if not isinstance(expect, list):\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"verify_state requires expect (array of predicates)\",\n                            effect_state=EffectState.NONE)\n    values: dict[str, Any] = {\"pid\": p[\"pid\"], \"window_id\": window_id,\n                              \"expect\": expect}\n    # session is deliberately NOT forwarded (the b19 house pattern): the\n    # daemon owns the session envelope; a caller-side \"session\" key is a\n    # stray and never reaches the driver.\n    for key in (\"timeout_ms\", \"stable_samples\", \"include_screenshot\"):\n        if key in p:\n            values[key] = p[key]\n    from .desktop import driver_backend\n    # Above the adapter's 30 s VERIFY_DEADLINE so CUA's own bounded answer\n    # (timeout_ms up to 10000 + per-sample observe + the optional final\n    # screenshot observe) always arrives first - the launch_app 65 s\n    # precedent (actions.py:3051-3052). The default 5 s exchange deadline\n    # would cut a legitimate poll short as a transport loss (found in the\n    # b20 live rows, disclosed).\n    reply = driver_backend.try_call(\n        \"verify_state\", values, deadline=time.monotonic() + 35.0)\n    if reply is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"driver unavailable for verify_state; nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused verify_state on window {window_id}: \"\n            f\"{error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            effect_state=EffectState(\n                error.get(\"effect_state\", \"none\")))\n    result = reply.get(\"result\") or {}\n    # A verification changes nothing: effect none for EVERY status -\n    # satisfied, unsatisfied OR unknown are all successful replies (the\n    # clipboard_read/table_read precedent). CUA keeps action facts and\n    # verification facts SEPARATE (action-result-contract.md:3-11): status\n    # is payload and is never mapped into effect_state, never promoted, and\n    # a satisfied verify is never commit evidence for a preceding action.\n    out = dict(result)\n    out[\"effect_state\"] = \"none\"\n    out[\"via\"] = \"driver-verify_state\"\n    return out\n\n\ndef _set_window_frame(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"B18: CUA's set_window_frame - set one exact window's frame (the\n    desktop-coordinate space list_windows reports) and verify through an\n    independent DWM readback (impl_.rs:9412-9653 at the pin; the\n    mechanism is a composite: outer-frame compensation + SetWindowPos\n    SWP_NOACTIVATE|SWP_NOZORDER + a 6x40 ms visible-frame readback) -\n    driver-ONLY (the bring_to_front precedent: a bare ctypes twin would\n    replicate one call of the three, not CUA's mechanism). Presence and\n    numeric type ONLY locally (R10): finiteness, i32 range, rounding,\n    minimized/maximized/pid ownership are the driver's checks.\"\"\"\n    window_id = p.get(\"window_id\")\n    if isinstance(window_id, bool) or not isinstance(window_id, int):\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"set_window_frame requires window_id (integer)\",\n                            effect_state=EffectState.NONE)\n    if p.get(\"pid\") is None:\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            \"set_window_frame requires pid\",\n                            effect_state=EffectState.NONE)\n    for key in (\"x\", \"y\", \"width\", \"height\"):\n        value = p.get(key)\n        if isinstance(value, bool) or not isinstance(value, (int, float)):\n            raise ProtocolError(ErrorCode.UNSUPPORTED,\n                                f\"set_window_frame requires {key} (number)\",\n                                effect_state=EffectState.NONE)\n    values: dict[str, Any] = {\"pid\": p[\"pid\"], \"window_id\": window_id,\n                              \"x\": p[\"x\"], \"y\": p[\"y\"],\n                              \"width\": p[\"width\"], \"height\": p[\"height\"]}\n    from .desktop import driver_backend\n    reply = driver_backend.try_call(\"set_window_frame\", values)\n    if reply is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"driver unavailable for set_window_frame; nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused set_window_frame on window {window_id}: \"\n            f\"{error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            effect_state=EffectState(\n                error.get(\"effect_state\", \"none\")))\n    result = reply.get(\"result\") or {}\n    # The honest mapping (_driver_effect, actions.py:379-389): CUA's\n    # confirmed WITH its own DWM readback evidence is COMMITTED - the\n    # first batch verb with a CUA-proven readback; everything else\n    # (unverifiable, suspected_noop, or a bare confirmed without\n    # evidence) stays unknown. A success is NEVER none.\n    raw_effect = result.get(\"effect\", \"\")\n    evidence = result.get(\"evidence\")\n    state = (\"committed\" if raw_effect == \"confirmed\"\n             and isinstance(evidence, list) and evidence else \"unknown\")\n    out = dict(result)\n    out[\"effect_state\"] = state\n    out[\"window_id\"] = window_id\n    out[\"via\"] = \"driver-set_window_frame\"\n    return out\n\n\ndef _accessibility_tree(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"B21: CUA's get_accessibility_tree - the fast DESKTOP snapshot, not a\n    subtree walk (impl_.rs:8958-9027 at the pin): the toolhelp process table\n    plus the merged EnumWindows(z-order)+UIA top-level window list. Driver-\n    only (R10): AutoSkill's own inventories stay as they are - desktop.apps\n    is the Start-menu/package inventory and desktop.observe is the per-window\n    UIA subtree; neither returns both tables in one call. The schema is EMPTY\n    and closed (the b16 list_apps shape): the wire call is ALWAYS {} and any\n    caller key (session included) is dropped before the wire. There is NO\n    refusal path in CUA's tool - an empty desktop is a SUCCESSFUL snapshot;\n    every refusal that can reach a caller is adapter-side or transport-side.\"\"\"\n    from .desktop import driver_backend\n    # session and strays are deliberately NOT forwarded (the b19 house\n    # rule): the daemon owns the session envelope.\n    reply = driver_backend.try_call(\"accessibility_tree\", {})\n    if reply is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"driver unavailable for accessibility_tree; \"\n            \"nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused accessibility_tree: \"\n            f\"{error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            effect_state=EffectState(\n                error.get(\"effect_state\", \"none\")))\n    result = reply.get(\"result\") or {}\n    # A read changes nothing (the clipboard_read/table_read precedent).\n    # CUA's rows pass through VERBATIM and additively (I7): no counts, no\n    # filtering, no merge into AutoSkill's window row shape - there is no\n    # pre-existing public row contract to keep (not the b16 case).\n    out = dict(result)\n    out[\"effect_state\"] = \"none\"\n    out[\"via\"] = \"driver-accessibility_tree\"\n    return out\n\n\ndef _geometry_read(method: str) -> dict[str, Any]:\n    from .desktop import driver_backend\n    reply = driver_backend.try_call(method, {})\n    if reply is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver unavailable for {method}; nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused {method}: {error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            effect_state=EffectState(error.get(\"effect_state\", \"none\")))\n    out = dict(reply.get(\"result\") or {})\n    out[\"effect_state\"] = \"none\"\n    out[\"via\"] = f\"driver-{method}\"\n    return out\n\n\ndef _screen_size(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    return _geometry_read(\"screen_size\")\n\n\ndef _cursor_position(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    return _geometry_read(\"cursor_position\")\n\n\ndef _move_cursor(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    scope = p.get(\"scope\", \"desktop\")\n    if scope != \"desktop\":\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"move_cursor supports only scope `desktop`; nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    import math\n    for key in (\"x\", \"y\"):\n        value = p.get(key)\n        if (isinstance(value, bool) or not isinstance(value, (int, float))\n                or not math.isfinite(value)):\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED,\n                f\"move_cursor requires numeric {key}; nothing was dispatched\",\n                effect_state=EffectState.NONE)\n    from .desktop import driver_backend\n    params = {\"x\": p[\"x\"], \"y\": p[\"y\"], \"scope\": \"desktop\"}\n    reply = driver_backend.try_call(\"move_cursor\", params)\n    if reply is None:\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            \"driver unavailable for move_cursor; nothing was dispatched\",\n            effect_state=EffectState.NONE)\n    if not reply.get(\"ok\"):\n        error = reply.get(\"error\") or {}\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED,\n            f\"driver refused move_cursor: {error.get('code', 'driver_error')}: \"\n            f\"{error.get('message', '')}\",\n            effect_state=EffectState(error.get(\"effect_state\", \"none\")))\n    out = dict(reply.get(\"result\") or {})\n    out[\"effect_state\"] = \"unknown\"\n    out[\"via\"] = \"driver-move_cursor\"\n    return out\n\n\ndef _open_app(s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    res = actions.open_app(str(p[\"command\"]), args=p.get(\"args\"),\n                           wait_title=p.get(\"wait_title\"),\n                           timeout=float(p.get(\"timeout\", 20)),\n                           start_minimized=bool(p.get(\"start_minimized\", False)),\n                           urls=p.get(\"urls\"))\n    if res.get(\"title\"):\n        s.last_window = res[\"title\"]\n    return res\n\n\n# --- human in the loop -------------------------------------------------------\n\ndef _request_help(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    prompt = str(p.get(\"prompt\") or \"\").strip()\n    if not prompt:\n        raise ProtocolError(ErrorCode.UNSUPPORTED, \"--prompt is required\")\n    timeout = int(p.get(\"timeout\", 180))\n    granted = d.confirmations.ask(session=s.id, method=\"human.request_help\",\n                                  detail=prompt, timeout=timeout)\n    return {\"outcome\": \"completed\" if granted else \"timed_out\",\n            \"prompt\": prompt,\n            \"effect_state\": EffectState.NONE.value,\n            \"note\": (\"The user reported the step done. Observe again and use \"\n                     \"fresh refs.\" if granted else\n                     \"No human action was confirmed. Do not repeat this \"\n                     \"request; report the blocker instead.\")}\n\n\n# --- browser -----------------------------------------------------------------\n\ndef _page(s: \"Session\"):\n    if s.browser_page is None:\n        raise ProtocolError(\n            ErrorCode.NO_SESSION, \"no browser is open for this session\",\n            hint=\"Run `auto browser open` first.\")\n    return s.browser_page\n\n\ndef _page_t(s: \"Session\", p: dict[str, Any]):\n    \"\"\"The page a verb acts on: `tab_id` if given, else the active tab.\n\n    BrowserSkill passed --tab-id on 84% of its commands; a single-page-per-\n    session model forces an agent to juggle state through back-navigation\n    instead of keeping pages open. Each tab owns its own ref store, so refs\n    from one tab are never valid in another — same generation contract, one\n    namespace per tab.\n    \"\"\"\n    tab = p.get(\"tab_id\")\n    if not tab:\n        return _page(s)\n    page = s.browser_pages.get(str(tab))\n    if page is None:\n        known = \", \".join(s.browser_pages) or \"none\"\n        raise ProtocolError(\n            ErrorCode.UNKNOWN_REF, f\"unknown tab {tab!r}\",\n            hint=f\"Open tabs: {known}. Run `auto browser tab list`.\")\n    return page\n\n\ndef _next_tab_id(s: \"Session\") -> str:\n    s.browser_tab_seq += 1\n    return f\"t{s.browser_tab_seq}\"\n\n\ndef _register_tab(s: \"Session\", page, *, make_active: bool = True) -> str:\n    tid = _next_tab_id(s)\n    s.browser_pages[tid] = page\n    if make_active:\n        s.browser_page = page\n    return tid\n\n\ndef _tab_new(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    if s.browser is None:\n        raise ProtocolError(\n            ErrorCode.NO_SESSION, \"no browser is open for this session\",\n            hint=\"Run `auto browser open` first.\")\n    from .browser.page import Page\n    # fix-r2 T12: the tab starts blank and a given url loads through Page.navigate (its load wait, ref reset and\n    # popup hook), so the answer is the url's page; navigate() normalises a scheme-less url itself.\n    url = p.get(\"url\")\n    tid_target, sess = s.browser.new_page(\"about:blank\")\n    page = Page(s.browser, tid_target, sess)\n    page.enable()\n    tab_id = _register_tab(s, page)\n    try:\n        s.browser.send(\"Target.activateTarget\", {\"targetId\": tid_target},\n                       timeout=15)\n    except ProtocolError:\n        pass   # activation is a convenience; the tab works regardless\n    if url:\n        page.navigate(url)\n    page._page_info()\n    return {\"effect_state\": \"committed\", \"tab_id\": tab_id,\n            \"url\": page.current_url, \"title\": page._page_info()[\"title\"],\n            \"tabs\": len(s.browser_pages)}\n\n\ndef _tab_list(s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    if s.browser is None:\n        raise ProtocolError(\n            ErrorCode.NO_SESSION, \"no browser is open for this session\",\n            hint=\"Run `auto browser open` first.\")\n    tabs = []\n    for tab_id, page in s.browser_pages.items():\n        try:\n            info = page._page_info()\n        except Exception:\n            info = {\"url\": page.current_url, \"title\": \"\"}\n        tabs.append({\"tab_id\": tab_id, \"url\": info.get(\"url\", \"\"),\n                     \"title\": info.get(\"title\", \"\"),\n                     \"active\": page is s.browser_page,\n                     \"refs\": len(page.refs)})\n    return {\"effect_state\": \"none\", \"tabs\": tabs, \"count\": len(tabs)}\n\n\ndef _tab_select(s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    tab = str(p.get(\"tab_id\") or \"\")\n    page = s.browser_pages.get(tab)\n    if page is None:\n        known = \", \".join(s.browser_pages) or \"none\"\n        raise ProtocolError(\n            ErrorCode.UNKNOWN_REF, f\"unknown tab {tab!r}\",\n            hint=f\"Open tabs: {known}. Run `auto browser tab list`.\")\n    s.browser_page = page\n    try:\n        s.browser.send(\"Target.activateTarget\",\n                       {\"targetId\": page.target_id}, timeout=15)\n    except ProtocolError:\n        pass\n    info = page._page_info()\n    return {\"effect_state\": \"committed\", \"tab_id\": tab,\n            \"url\": info.get(\"url\", \"\"), \"title\": info.get(\"title\", \"\")}\n\n\ndef _tab_close(s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    tab = str(p.get(\"tab_id\") or \"\")\n    page = s.browser_pages.get(tab)\n    if page is None:\n        # Closing by position from the right is the browser convention.\n        if s.browser_pages:\n            tab = list(s.browser_pages)[-1]\n            page = s.browser_pages[tab]\n        else:\n            raise ProtocolError(\n                ErrorCode.UNKNOWN_REF, \"no tabs are open\",\n                hint=\"Run `auto browser tab new` first.\")\n    was_active = page is s.browser_page\n    try:\n        s.browser.send(\"Target.closeTarget\",\n                       {\"targetId\": page.target_id}, timeout=15)\n    finally:\n        s.browser_pages.pop(tab, None)\n        if was_active:\n            # Fall back to the most recently opened remaining tab, if any.\n            # `dict_values` is not subscriptable, so slicing the view\n            # raised TypeError inside this `finally` — every close of\n            # the ACTIVE tab crashed. Materialise the list, then slice.\n            remaining = list(s.browser_pages.values())\n            s.browser_page = remaining[-1] if remaining else None\n    return {\"effect_state\": \"committed\", \"closed\": tab,\n            \"tabs\": len(s.browser_pages)}\n\n\ndef _browser_choice(p: dict[str, Any], d: \"Daemon\") -> tuple[str | None, str]:\n    \"\"\"Resolve which browser to open: explicit --browser, then the user's\n    pinned default, then installed-preference order.\n\n    The default is user-owned (`auto config set default-browser`, written to\n    policy.json from the shell) so that which browser automation drives is\n    the user's standing decision, not a silent preference order — the agent\n    is told to ask when nothing is pinned.\n    \"\"\"\n    explicit = p.get(\"browser\")\n    if explicit:\n        return str(explicit), \"explicit\"\n    pinned = getattr(d.policy, \"default_browser\", None)\n    if pinned:\n        return str(pinned), \"default\"\n    return None, \"preference\"\n\n\ndef _profile_key(which: str | None) -> str:\n    \"\"\"A short, filesystem-safe profile suffix for a browser name or path.\n\n    A full path used to become the suffix verbatim, backslashes and all.\n    \"\"\"\n    if not which:\n        return \"\"\n    from .browser.cdp import BROWSERS\n    key = which.strip().lower()\n    if key in BROWSERS:\n        return key\n    from pathlib import PureWindowsPath\n    return PureWindowsPath(which).stem.lower() or \"custom\"\n\n\ndef _browser_open(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    from .browser.cdp import CdpConnection\n    from .browser.page import Page\n    if s.browser is not None:\n        return {\"already_open\": True, \"effect_state\": \"none\",\n                \"profile\": str(d.home / \"browser-profile\")}\n    which, source = _browser_choice(p, d)\n    # A separate profile per browser: one user-data-dir cannot be shared\n    # between Chrome and Edge, and mixing them corrupts it.\n    key = _profile_key(which)\n    profile = d.home / (\"browser-profile-\" + key if key else \"browser-profile\")\n    # Fresh-profile detection: a marker written after the first successful\n    # open. Its absence means nothing has ever signed in here, and the agent\n    # should get the user to sign in once (request-help) rather than assume\n    # an account exists — the user's real Chrome profile is deliberately not\n    # reused: Chrome refuses remote debugging on it, and driving a profile\n    # with the user's whole signed-in life would remove the sandbox boundary\n    # the dedicated profile exists to provide.\n    marker = profile / \".autoskill-initialized\"\n    first_run = not marker.exists()\n    conn = CdpConnection(user_data_dir=profile,\n                         browser_path=which,\n                         headless=bool(p.get(\"headless\")),\n                         start_url=\"about:blank\")     # fix-r2 T12: a given url loads below, through Page.navigate\n    conn.start()\n    def _page_targets():\n        # One patient retry: a cold Chrome spawn is occasionally held up for\n        # tens of seconds by on-access scanning of the profile directory, and\n        # the first CDP reply then misses the 30s budget even though the\n        # browser is fine. Retrying once after a beat recovers it without\n        # hiding a real failure.\n        try:\n            return [t for t in conn.targets() if t.get(\"type\") == \"page\"]\n        except ProtocolError:\n            time.sleep(12)\n            return [t for t in conn.targets() if t.get(\"type\") == \"page\"]\n    try:\n        targets = _page_targets()\n        if targets:\n            tid = targets[0][\"targetId\"]\n            sess = conn.attach_page(tid)\n        else:\n            tid, sess = conn.new_page(\"about:blank\")\n    except ProtocolError:\n        # A half-open browser is worse than none: the next open against the\n        # same profile meets Chrome's singleton hand-off to a zombie and\n        # fails the same way, forever. Close what we started before raising.\n        conn.close()\n        raise\n    from .browser import reaper\n    reaper.register(d.home, browser_pid=conn.browser_pid,\n                    bridge_pid=conn.bridge_pid, profile=profile)\n    s.browser = conn\n    s.browser_pages = {}\n    s.browser_tab_seq = 0\n    page = Page(conn, tid, sess)\n    page.enable()\n    _register_tab(s, page)\n    page._page_info()\n    try:\n        marker.parent.mkdir(parents=True, exist_ok=True)\n        marker.write_text(\"initialized\", encoding=\"utf-8\")\n    except OSError:\n        pass\n    out = {\"effect_state\": \"committed\", \"browser_pid\": conn.browser_pid,\n           \"profile\": str(profile), \"browser_path\": conn.browser_path,\n           \"browser_source\": source,\n           \"tab_id\": next(iter(s.browser_pages)),\n           \"note\": (\"This is a dedicated profile. Sign in once per site; the \"\n                    \"session persists. No debugging port is opened.\")}\n    if p.get(\"url\"):                    # fix-r2 T12: answer only once the url's page is there\n        landed = page.navigate(str(p[\"url\"]))\n        out.update(url=landed.get(\"url\"), title=landed.get(\"title\"))\n    if first_run:\n        out[\"fresh_profile\"] = True\n        out[\"sign_in_hint\"] = (\n            \"Nothing is signed in on this first run of this profile. For \"\n            \"each site that needs the user's account, ask them to sign in \"\n            \"once with `request-help` — the login persists in this profile \"\n            \"for future sessions. Note: Google refuses sign-in inside automation-\"\n            \"controlled browsers; for Gmail/Google services, have the user \"\n            \"work in their own browser instead.\")\n    if not which:\n        from .browser.cdp import available_browsers\n        found = [b[\"name\"] for b in available_browsers()]\n        out[\"browser_note\"] = (\n            \"opened by preference order; the user can pin theirs with \"\n            \"`auto config set default-browser <\" + \"|\".join(found) + \">`\")\n    return out\n\n\ndef _browser_shot(s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    out = p.get(\"out\") or str(Path(tempfile.gettempdir())\n                              / f\"autoskill-page-{int(time.time())}.png\")\n    return _page_t(s, p).screenshot(out, full_page=bool(p.get(\"full_page\")),\n                                    lazy=bool(p.get(\"lazy\")))\n\n\ndef _browser_close(s: \"Session\", home=None) -> dict[str, Any]:\n    if s.browser is None:\n        return {\"effect_state\": \"none\", \"note\": \"no browser was open\"}\n    if home is not None:\n        from .browser import reaper\n        reaper.unregister(home, s.browser.browser_pid)\n    s.browser.close()\n    s.browser = None\n    s.browser_page = None\n    s.browser_pages = {}\n    s.browser_tab_seq = 0\n    return {\"effect_state\": \"committed\", \"closed\": True}\n\n\ndef _dialog_policy(page, p: dict[str, Any]) -> dict[str, Any]:\n    policy = str(p.get(\"policy\") or \"\").lower()\n    if policy not in (\"dismiss\", \"accept\"):\n        raise ProtocolError(\n            ErrorCode.UNSUPPORTED, f\"unknown dialog policy {policy!r}\",\n            hint=\"Use dismiss (Cancel/OK-only) or accept (confirm OK). \"\n                 \"dismiss is the default because accepting a confirm() on the \"\n                 \"agent's behalf is a decision the user did not make.\")\n    page.dialog_policy = policy\n    return {\"effect_state\": \"none\", \"dialog_policy\": policy}\n\n\ndef _flow_resolve(name: str):\n    \"\"\"A bare name means an installed profile; anything else is a path.\"\"\"\n    from .workflow import Profile, profiles_dir\n    p = Path(name)\n    if not p.suffix and not p.exists():\n        p = profiles_dir() / f\"{name}.json\"\n    return Profile.load(p)\n\n\ndef _flow_list() -> dict[str, Any]:\n    from .workflow import list_profiles\n    rows = list_profiles()\n    return {\"effect_state\": \"none\", \"profiles\": rows, \"count\": len(rows)}\n\n\ndef _flow_validate(name: str) -> dict[str, Any]:\n    prof = _flow_resolve(name)          # raises with the reason if unusable\n    return {\"effect_state\": \"none\", \"valid\": True, **prof.summary()}\n\n\ndef _flow_runner(d: \"Daemon\", name: str, tag: str = \"S1\"):\n    from .workflow import FlowRunner\n    return FlowRunner(_flow_resolve(name), home=d.home, session_tag=tag)\n\n\ndef _flow_analyse(d: \"Daemon\", s: \"Session | None\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Observe a tab, then describe its structure. Reads only.\n\n    This is the step that was missing. Patterns were written by hand\n    against a remembered page, and a pattern that matches nothing fails\n    silently - measured: a declared pagination control that does not\n    exist, so the queue was never expanded and nothing complained.\n    \"\"\"\n    from .analyse import analyse, interface_report, suggest_profile\n    surface = str(p.get(\"surface\") or \"rb\")\n    method = (Method.RB_OBSERVE.value if surface == \"rb\"\n              else Method.BROWSER_OBSERVE.value)\n    handler = d._handlers.get(method)\n    if handler is None:\n        raise ProtocolError(ErrorCode.UNSUPPORTED,\n                            f\"no observe verb for surface {surface!r}\")\n    if surface != \"rb\" and s is None:\n        # sw1 R5: the dedicated browser belongs to a session (rb.observe needs none).\n        raise ProtocolError(ErrorCode.NO_SESSION,\n                            \"surface browser reads the session's own browser: pass session_id\")\n    # No token budget: the analysis exists to see the WHOLE page, and a\n    # truncated read is exactly the trap it is meant to expose.\n    obs = handler(s, {\"tab_id\": p.get(\"tab_id\"), \"max_tokens\": None})\n    text = obs.get(\"text\", \"\")\n    out = analyse(text)\n    out[\"interface\"] = interface_report(text)\n    if obs.get(\"site\"):\n        out[\"site\"] = obs[\"site\"]\n    out[\"surface\"] = surface\n    out[\"tab_id\"] = obs.get(\"tab_id\")\n    if p.get(\"emit\"):\n        import json as _json\n        draft = suggest_profile(text, str(p.get(\"name\") or \"draft\"),\n                                surface)\n        path = Path(str(p[\"emit\"])).expanduser()\n        path.parent.mkdir(parents=True, exist_ok=True)\n        path.write_text(_json.dumps(draft, ensure_ascii=False, indent=2)\n                        + \"\\n\", encoding=\"utf-8\")\n        out[\"emitted\"] = str(path)\n        out[\"note\"] = (\"A DRAFT profile was written. Its gates are \"\n                       \"placeholders - policy is not visible in a page. \"\n                       \"Fill them in, then `auto flow validate`.\")\n    return out\n\n\ndef _scratch_png(d: \"Daemon\", s: \"Session\", kind: str) -> Path:\n    \"\"\"A capture path in the session's scratch, removed with the session:\n    a picture of the user's screen is not kept by default.\"\"\"\n    scratch = d.home / \"scratch\" / s.id\n    scratch.mkdir(parents=True, exist_ok=True)\n    return scratch / f\"{kind}-{int(time.time() * 1000)}.png\"\n\n\ndef _rb_analyse(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"The whole interface of a tab: structure, element kinds, readability\n    (checked by OCR when asked), recommended methods, and whether the site\n    changed since it was learned. Reads only.\"\"\"\n    from .analyse import analyse, interface_report\n    # With the pixel fallback: a page whose tree times out is analysed from\n    # what is drawn instead of failing the analysis (T6).\n    obs = d.rb.observe(p.get(\"tab_id\"), max_tokens=None, fallback=True)\n    if obs.get(\"mode\") == \"ocr\":\n        lines = obs.get(\"lines\") or []\n        return {\"effect_state\": \"none\", \"tab_id\": obs.get(\"tab_id\"),\n                \"surface\": \"rb\", \"mode\": \"ocr\",\n                \"interface\": {\n                    \"readability\": \"unreadable\",\n                    \"counts\": {\"ocr_lines\": len(lines)},\n                    \"named_share\": 0.0, \"frames\": 0, \"ocr\": None,\n                    \"recommended\": [\n                        \"the tree cannot be read here: find text with `rb ocr \"\n                        \"--find`, press text with `rb act --text`, press an \"\n                        \"icon with `rb act --near TEXT --pick right|left|N|\"\n                        \"name:WORD` (list them with `rb locate --near TEXT`)\"],\n                    \"notes\": [f\"accessibility tree unavailable: \"\n                              f\"{obs.get('tree_error')}\"],\n                    \"elements\": {}},\n                \"ocr_lines\": [ln[\"text\"] for ln in lines][:200],\n                \"site\": obs.get(\"site\"), \"notes\": []}\n    # The tree alone: on a page known to be partial the observation already\n    # carries the OCR lines, and measured against itself it read 100% (S141).\n    text = obs.get(\"tree_text\") or obs.get(\"text\", \"\")\n    ocr_text = None\n    ocr_note = None\n    # On by default: a tree that answers can still miss the page (T10), and\n    # only the pixels show it. `ocr: false` skips the check.\n    if p.get(\"ocr\", True):\n        try:\n            seen = d.rb.ocr(obs.get(\"tab_id\"))\n            ocr_text = \"\\n\".join(ln[\"text\"] for ln in seen.get(\"lines\") or [])\n        except ProtocolError as exc:\n            ocr_note = f\"OCR not available: {exc.error.message}\"\n    out = analyse(text)\n    out[\"interface\"] = interface_report(text, ocr_text)\n    # What the tool already knows about this page, to use it (S145): the\n    # procedures that pass through it, the proven method per control, what\n    # got stuck and what got it through.\n    try:\n        out[\"memory\"] = d.sites.page_memory(d.rb.url_of(obs.get(\"tab_id\")))\n    except Exception:\n        pass\n    if ocr_note:\n        out[\"interface\"][\"notes\"].append(ocr_note)\n    cov = (out[\"interface\"].get(\"ocr\") or {}).get(\"coverage\")\n    if cov is not None:\n        d.rb.note_tree_coverage(d.rb.url_of(obs.get(\"tab_id\")), cov)\n    out[\"site\"] = obs.get(\"site\")\n    out[\"tab_id\"] = obs.get(\"tab_id\")\n    out[\"surface\"] = \"rb\"\n    return out\n\n\ndef _site_check(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    obs = d.rb.observe(p.get(\"tab_id\"), max_tokens=None)\n    site = obs.get(\"site\") or {}\n    hint = {\n        \"known\": \"The interface matches what was learned; remembered steps \"\n                 \"and methods apply.\",\n        \"changed\": \"The page is recognised but its controls changed. Check \"\n                   \"the `breaking` list before replaying remembered steps; \"\n                   \"`auto site accept` makes the new interface the baseline.\",\n        \"new\": \"Nothing similar is known for this page yet; it has been \"\n               \"recorded as a new state.\",\n    }.get(site.get(\"status\", \"\"), \"\")\n    return {\"effect_state\": \"none\", \"tab_id\": obs.get(\"tab_id\"), **site,\n            \"hint\": hint}\n\n\ndef _research_document(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    from .contracts.models import ResearchDocumentRequest\n    document = d.research.read(ResearchDocumentRequest(\n        p[\"url\"], max(100, min(int(p.get(\"max_chars\", 12000)), 50000))))\n    return {\"effect_state\": \"none\", \"source_url\": document.source_url,\n            \"retrieved_at\": document.retrieved_at, \"sha256\": document.sha256,\n            \"content_type\": document.content_type, \"text\": document.text,\n            \"truncated\": document.truncated,\n            \"trust\": \"untrusted evidence; validate procedures against the current UI before learning\"}\n\n\ndef _research(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    from .contracts.research_catalog import SOURCES\n    from .contracts.models import ResearchRequest\n    from .contracts.browser_memory import MemoryWriteStatus, ResearchFeedback\n    report = d.research.search_sources(\n        ResearchRequest((str(p.get(\"query\") or \"\"),), max(1, min(int(p.get(\"limit\") or 5), 10))),\n        tuple(p.get(\"sources\") or SOURCES))\n    run = report.result.runs[0]\n    results = [{\"source\": hit.source, \"title\": hit.title, \"url\": hit.url, \"kind\": hit.kind,\n                **({\"about\": hit.about} if hit.about else {})}\n               for hit in run.results]\n    kinds: dict[str, int] = {}\n    for hit in run.results:\n        kinds[hit.kind] = kinds.get(hit.kind, 0) + 1\n    res = {\"effect_state\": \"none\", \"query\": run.query, \"results\": results,\n           \"count\": len(results), \"by_kind\": kinds,\n           \"queries_used\": {item.name: item.value for item in report.queries_used},\n           \"sent_to\": list(report.sent_to),\n           \"failures\": {name: \"source unavailable\" for name in run.failed_sources}}\n    if p.get(\"site\"):\n        status = d.browser_memory.remember(ResearchFeedback(str(p[\"site\"]), run))\n        if status is MemoryWriteStatus.STORED:\n            res[\"kept_in\"] = f\"site memory of {p['site']}\"\n            _knowing(d, res)\n        else:\n            res[\"memory_status\"] = status.value\n    return res\n\n\ndef _knowing(d: \"Daemon\", result: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Bring the site knowledge graph up to date in the background (S145),\n    after anything that adds knowledge: a recipe, research, a recording, a\n    replay. Never delays or fails the call it follows.\"\"\"\n    try:\n        from . import siteknow\n        siteknow.refresh(d.sites, d.memory_home)\n    except Exception:\n        pass\n    return result\n\n\ndef _site_replay(d: \"Daemon\", p: dict[str, Any], session=None) -> dict[str, Any]:\n    from .replay import replay\n    from .contracts.grounding import site_key\n    from .protocol import Request, ProtocolError, EffectState\n    def dispatch(method, params):\n        response = d.handle(Request(method=method, params=params,\n                                    session=session.id if session else None))\n        if not response.ok:\n            error = response.error or {\"code\": \"internal\", \"message\": \"missing error\"}\n            raise ProtocolError(ErrorCode(error[\"code\"]), error[\"message\"], hint=error.get(\"hint\"),\n                                effect_state=EffectState(error.get(\"effect_state\", \"none\")))\n        return response.result\n    tab = d.rb.pick_tab(p.get(\"tab_id\"))\n    host = str(p.get(\"host\") or site_key(d.rb.url_of(tab))[0])\n    texts = {}\n    for item in p.get(\"texts\") or []:\n        k, _, v = str(item).partition(\"=\")\n        texts[k] = v\n    return _knowing(d, replay(d.rb, d.sites, host, str(p[\"name\"]), tab_id=tab,\n                              dry_run=bool(p.get(\"dry_run\")),\n                              allow_irreversible=bool(p.get(\"allow_irreversible\")),\n                              texts=texts, dispatch=dispatch))\n\n\ndef _site_know(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    from . import siteknow\n    action = str(p.get(\"action\") or \"status\")\n    if action == \"build\":\n        return {\"effect_state\": \"committed\",\n                **(siteknow.refresh(d.sites, d.memory_home, wait=True) or {})}\n    if action in (\"ask\", \"query\", \"explain\", \"search\"):\n        kind = \"query\" if action in (\"ask\", \"query\") else action\n        return {\"effect_state\": \"none\",\n                **siteknow.ask(d.memory_home, str(p.get(\"words\") or \"\"), kind=kind)}\n    if action == \"lesson\":\n        return {\"effect_state\": \"committed\",\n                **siteknow.lesson(d.memory_home, str(p.get(\"words\") or \"\"),\n                                  str(p.get(\"answer\") or \"\"),\n                                  list(p.get(\"nodes\") or []),\n                                  str(p.get(\"outcome\") or \"useful\"))}\n    root = siteknow.knowledge_dir(d.memory_home)\n    return {\"effect_state\": \"none\", \"folder\": str(root),\n            \"built\": (root / \"kgraph-out\" / \"graph.json\").is_file(),\n            \"hosts\": sorted(x.name for x in root.iterdir() if x.is_dir()\n                            and x.name != \"kgraph-out\") if root.is_dir() else []}\n\n\ndef _flow_status(d: \"Daemon\", name: str) -> dict[str, Any]:\n    r = _flow_runner(d, name)\n    rows = r.journal_rows()\n    counts: dict[str, int] = {}\n    for row in rows:\n        counts[row.get(\"action\", \"?\")] = counts.get(row.get(\"action\", \"?\"), 0) + 1\n    # \"committing\" with no matching \"acted\" is the honest unknown: the\n    # irreversible step was dispatched and the confirmation never landed.\n    done = {x.get(\"identity\") for x in rows if x.get(\"action\") == \"acted\"}\n    inflight = [x for x in rows if x.get(\"action\") == \"committing\"\n                and x.get(\"identity\") not in done]\n    return {\"effect_state\": \"none\", \"profile\": r.p.name,\n            \"journal\": str(r.journal), \"rows\": len(rows),\n            \"actions\": counts, \"decided\": len(r.decided()),\n            \"unconfirmed\": [x.get(\"summary\") for x in inflight],\n            \"recent\": rows[-8:]}\n\n\ndef _flow_reconcile(d: \"Daemon\", name: str) -> dict[str, Any]:\n    return _flow_runner(d, name).reconcile()\n\n\ndef _flow_start(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Launch a run in its own process and return at once.\n\n    Holding an RPC open for hours would pin a daemon thread and make\n    the run invisible to everything else. Detached, it is supervised by\n    `auto watch` and inspected by `flow.status` like any other job.\n    \"\"\"\n    import subprocess\n    import sys\n    name = str(p[\"profile\"])\n    runner = _flow_runner(d, name, str(p.get(\"tag\") or \"S1\"))\n    log = d.home / f\"flow-{runner.p.name}.log\"\n    argv = [sys.executable, \"-m\", \"autoskill\", \"flow\", \"run\", name,\n            \"--minutes\", str(float(p.get(\"minutes\") or 60)),\n            \"--tag\", str(p.get(\"tag\") or \"S1\")]\n    if p.get(\"max_items\"):\n        argv += [\"--max-items\", str(int(p[\"max_items\"]))]\n    if p.get(\"dry_run\"):\n        argv.append(\"--dry-run\")\n    if int(p.get(\"repeat\") or 1) > 1:\n        argv += [\"--repeat\", str(int(p[\"repeat\"]))]\n    from .hidden import no_window_flags\n    flags = no_window_flags()        # never with DETACHED_PROCESS (hidden.py)\n    with open(log, \"a\", encoding=\"utf-8\") as fh:\n        proc = subprocess.Popen(argv, stdout=fh, stderr=fh,\n                                stdin=subprocess.DEVNULL,\n                                creationflags=flags,\n                                env={**os.environ,\n                                     \"AUTOSKILL_HOME\": str(d.home)})\n    d.run_control.add_flow(proc.pid, runner.p.name, str(log), str(runner.journal),\n                           str(runner.p.path or \"\"))\n    d.run_control.open_dashboard(\"flow\")\n    return {\"effect_state\": \"committed\", \"started\": True, \"pid\": proc.pid,\n            \"profile\": runner.p.name, \"log\": str(log),\n            \"journal\": str(runner.journal),\n            \"dry_run\": bool(p.get(\"dry_run\")),\n            \"note\": (\"Supervise it: `auto watch --log <log> --journal \"\n                     \"<journal>`. Inspect it: flow_status.\")}\n\n\ndef _watch_status(d: \"Daemon\") -> dict[str, Any]:\n    from .watchdog import read_state\n    return read_state(d.home)\n\n\ndef _watch_timeline(d: \"Daemon\", limit: int) -> dict[str, Any]:\n    from .watchdog import read_timeline\n    return read_timeline(d.home, limit)\n\n\ndef _driver_signature() -> tuple[bool, str, str]:\n    if os.name != \"nt\":\n        return True, \"not checked (Authenticode is Windows-only)\", \"\"\n    import json\n    import subprocess\n    from .hidden import hidden\n    from .resources import asset\n    try:\n        executable = asset(\"native/driver/autoskill-driver.exe\")\n        quoted = str(executable).replace(\"'\", \"''\")\n        script = (\n            f\"$s = Get-AuthenticodeSignature -FilePath '{quoted}'; \"\n            \"[pscustomobject]@{Status=[string]$s.Status;StatusMessage=$s.StatusMessage} \"\n            \"| ConvertTo-Json -Compress\"\n        )\n        completed = subprocess.run(\n            [\"powershell.exe\", \"-NoProfile\", \"-NonInteractive\", \"-Command\", script],\n            capture_output=True, text=True, **hidden())\n        if completed.returncode != 0:\n            return True, f\"not checked (PowerShell exited {completed.returncode})\", \"\"\n        payload = json.loads(completed.stdout)\n        status = str(payload.get(\"Status\") or \"Unknown\")\n        message = str(payload.get(\"StatusMessage\") or \"\").strip()\n        detail = status + (f\": {message}\" if message else \"\")\n        if status == \"Valid\":\n            return True, detail, \"\"\n        return False, detail, \"Owner certificate required for H9; do not self-sign.\"\n    except Exception as exc:\n        return True, f\"not checked ({type(exc).__name__}: {exc})\", \"\"\n\n\ndef _node_for_doctor() -> str | None:\n    \"\"\"The Node the browser transport will use (the package's own first), or None.\"\"\"\n    from .browser import cdp\n    try:\n        return cdp.find_node()\n    except ProtocolError:\n        return None\n\n\ndef _doctor(d: \"Daemon\") -> dict[str, Any]:\n    \"\"\"Health check. Every entry says what to do when it is not ok.\"\"\"\n    import shutil\n    checks: list[dict[str, Any]] = []\n\n    def add(name, ok, detail, hint=\"\"):\n        checks.append({\"check\": name, \"ok\": bool(ok), \"detail\": detail,\n                       **({\"hint\": hint} if hint and not ok else {})})\n\n    def add_report(name, ok, detail, report, hint=\"\"):\n        row = {\"check\": name, \"ok\": bool(ok), \"detail\": detail, \"report\": report}\n        if hint and not ok:\n            row[\"hint\"] = hint\n        checks.append(row)\n\n    def diagnostic_error(reply):\n        if isinstance(reply, dict):\n            error = reply.get(\"error\") or {}\n            return (f\"{error.get('code') or 'driver_error'}: \"\n                    f\"{error.get('message') or 'no diagnostic response'}\")\n        return \"no diagnostic response\"\n\n    from .desktop import driver_backend\n    driver_health = driver_backend.health()\n    # Optional companion: missing/off retains the existing Python desktop path.\n    add(\"driver\", True, driver_health[\"detail\"])\n    add(\"driver signature\", *_driver_signature())\n\n    if driver_health[\"available\"]:\n        reply = driver_backend.try_call(\"health_report\", {}, deadline=time.monotonic() + 12)\n        if reply and reply.get(\"ok\"):\n            report = reply[\"result\"]\n            failed_health = [c for c in report.get(\"checks\", []) if c.get(\"status\") == \"fail\"]\n            overall = report.get(\"overall\", \"unknown\")\n            detail = (f\"{overall} - {report.get('platform', 'unknown')} \"\n                      f\"cua-driver {report.get('driver_version', 'unknown')}; \"\n                      f\"{len(report.get('checks', []))} checks\")\n            if failed_health:\n                first = failed_health[0]\n                detail += f\"; {first.get('name')}: {first.get('message')}\"\n            add_report(\"driver health\", overall == \"ok\", detail, report,\n                       failed_health[0].get(\"hint\", \"\") if failed_health else \"\")\n        else:\n            add(\"driver health\", False, diagnostic_error(reply))\n\n        reply = driver_backend.try_call(\"check_permissions\", {}, deadline=time.monotonic() + 12)\n        if reply and reply.get(\"ok\"):\n            report = reply[\"result\"]\n            elevation = \"elevated\" if report.get(\"elevated\") else \"non-elevated\"\n            detail = (f\"{report.get('integrity_level', 'Unavailable')} ({elevation}); \"\n                      f\"UIA={report.get('uia')}; PostMessage={report.get('post_message')}\")\n            add_report(\"driver permissions\", True, detail, report)\n        else:\n            add(\"driver permissions\", False, diagnostic_error(reply))\n\n        reply = driver_backend.try_call(\n            \"debug_window_info\", {\"pid\": os.getpid()}, deadline=time.monotonic() + 12)\n        if reply and reply.get(\"ok\"):\n            report = reply[\"result\"]\n            focused = report.get(\"focused_element\") or {}\n            patterns = focused.get(\"supported_patterns\") or []\n            detail = (f\"{len(report.get('windows', []))} windows; \"\n                      f\"target session {report.get('session_id')}, \"\n                      f\"driver session {report.get('daemon_session_id')}; \"\n                      f\"XAML recommended={report.get('xaml_routing_recommended')}; \"\n                      f\"focused patterns: {', '.join(patterns) or 'none'}\")\n            add_report(\"driver window info\", True, detail, report)\n        else:\n            add(\"driver window info\", False, diagnostic_error(reply))\n    else:\n        for name in (\"driver health\", \"driver permissions\", \"driver window info\"):\n            add(name, True, f\"not run ({driver_health['detail']})\")\n\n    try:\n        import uiautomation\n        from .desktop.executor import uia_call\n        # Independent UIA health probe: never route through the driver, or a\n        # healthy driver would conceal a broken Python UIA fallback (T2 note).\n        n = uia_call(lambda: len(actions.list_windows(via_driver=False)), timeout=60)\n        add(\"desktop (UIA)\", True, f\"{n} windows visible\")\n    except Exception as exc:\n        add(\"desktop (UIA)\", False, f\"{type(exc).__name__}: {exc}\",\n            \"pip install uiautomation comtypes\")\n\n    node = _node_for_doctor()\n    add(\"node (browser transport)\", bool(node), node or \"not found\",\n        \"Restore native/node/node.exe from the package or install Node.js; the browser layer needs it \"\n        \"to pass the CDP pipe. Desktop automation works without it.\")\n\n    from .browser.cdp import CHROME_CANDIDATES\n    from pathlib import Path as _P\n    browser = next((c for c in CHROME_CANDIDATES if _P(c).exists()), None)\n    add(\"chromium browser\", bool(browser), browser or \"none found\",\n        \"Install Chrome or Edge.\")\n\n    add(\"permission mode\", True, d.policy.mode.value)\n    quiet = not bool(getattr(d.policy, \"steal_focus\", False))\n    add(\"quiet while working\", True,\n        \"on - windows are not raised\" if quiet else\n        \"OFF - the tool takes the screen (auto config set steal-focus off)\")\n    # The bridge token drives the user REAL signed-in browser. It was once\n    # written with inherited ACLs, readable by every account on the machine;\n    # report the posture rather than assume it still holds.\n    try:\n        from .safety.fsacl import describe_acl, is_owner_only\n        from .nmhost import _bridge_endpoint_file\n        ep = _bridge_endpoint_file()\n        if ep.exists():\n            acl = describe_acl(ep)\n            add(\"bridge token acl\", is_owner_only(acl), acl[:110],\n                \"Re-run `auto rb install` to rewrite it restricted.\")\n        else:\n            add(\"bridge token acl\", True, \"no bridge host registered\")\n    except Exception as exc:\n        add(\"bridge token acl\", True, f\"not checked ({type(exc).__name__})\")\n    add(\"audit log\", d.audit.enabled, str(d.audit.path))\n    # Links that live outside the project folder (venv import path, PATH,\n    # bridge registrations) must name this folder, not a former one.\n    try:\n        from . import relocation\n        root = relocation.checkout_root()\n        if root is None:\n            add(\"project folder links\", True, \"installed runtime (no project folder)\")\n        else:\n            bad = [f for f in relocation.inspect(root, d.home) if not f.ok]\n            add(\"project folder links\", not bad,\n                \"all point to \" + str(root) if not bad else \"; \".join(f.detail for f in bad)[:200],\n                \"Run `auto relocate` to see each link and `auto relocate --apply` to repair them.\")\n    except Exception as exc:\n        add(\"project folder links\", True, f\"not checked ({type(exc).__name__})\")\n    try:\n        bridge = d.rb.status()\n        add(\"browser bridge handshake\", bridge.get(\"connected\") is True,\n            f\"extension version {bridge.get('version')}\", \"Reload autoskill bridge in the selected browser.\")\n    except Exception as exc:\n        add(\"browser bridge handshake\", False, str(exc)[:160],\n            \"Desktop may still work; start the configured browser and reload autoskill bridge.\")\n    reaped = getattr(d, \"reaped\", None) or {}\n    add(\"orphan reaping\", True,\n        f\"checked {reaped.get('checked', 0)}, reaped {reaped.get('reaped', 0)}\")\n    for name, ok, detail, hint in _dashboard_checks(d):\n        add(name, ok, detail, hint)\n    add(\"sessions\", True, f\"{len(d.sessions)} open\")\n\n    failed = [c[\"check\"] for c in checks if not c[\"ok\"]]\n    return {\"effect_state\": \"none\", \"checks\": checks,\n            \"ok\": not failed, \"failed\": failed}\n\n\ndef _browser_list() -> dict[str, Any]:\n    from .browser.cdp import available_browsers\n    found = available_browsers()\n    return {\"effect_state\": \"none\", \"browsers\": found,\n            \"default\": found[0][\"name\"] if found else None}\n\n\ndef _trace(d: \"Daemon\", p: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Summarise what actually happened, for fixing what went wrong.\n\n    The audit log is a flat stream; a post-mortem needs shape. This groups it\n    the way the failures in this project were actually found: which verbs run,\n    which fail, what follows what, and where the time goes.\n    \"\"\"\n    from collections import Counter\n    rows = d.audit.tail(int(p.get(\"count\", 2000)), p.get(\"session\"))\n    if not rows:\n        return {\"effect_state\": \"none\", \"entries\": 0}\n\n    verbs = Counter(r.get(\"method\", \"?\") for r in rows)\n    outcomes = Counter(r.get(\"outcome\", \"?\") for r in rows)\n    effects = Counter(r.get(\"effect_state\", \"?\") for r in rows)\n    failures = [r for r in rows if r.get(\"outcome\") != \"ok\"]\n\n    # What follows what: the pattern that exposed BrowserSkill's verify-after-\n    # click habit, and that shows a retry loop here.\n    pairs: Counter[tuple[str, str]] = Counter()\n    for a, b in zip(rows, rows[1:]):\n        pairs[(str(a.get(\"method\") or \"\"), str(b.get(\"method\") or \"\"))] += 1\n\n    slow = sorted(rows, key=lambda r: -(r.get(\"elapsed_ms\") or 0))[:5]\n    unverified = [r for r in rows\n                  if (r.get(\"result\") or {}).get(\"verified\") is False]\n\n    return {\n        \"effect_state\": \"none\",\n        \"entries\": len(rows),\n        \"verbs\": dict(verbs.most_common()),\n        \"outcomes\": dict(outcomes),\n        \"effect_states\": dict(effects),\n        \"failures\": [{\"method\": r.get(\"method\"),\n                      \"error\": (r.get(\"error\") or \"\")[:160],\n                      \"effect_state\": r.get(\"effect_state\"),\n                      \"target\": r.get(\"target\")} for r in failures[-12:]],\n        \"transitions\": [{\"from\": a, \"to\": b, \"n\": n}\n                        for (a, b), n in pairs.most_common(8)],\n        \"slowest_ms\": [{\"method\": r.get(\"method\"),\n                        \"ms\": r.get(\"elapsed_ms\")} for r in slow],\n        \"unverified_actions\": len(unverified),\n    }\n\n\ndef _record_start(d: \"Daemon\", s: \"Session\", p: dict[str, Any]) -> dict[str, Any]:\n    from .desktop.recording import DesktopRecording\n    if s.recording is not None:\n        raise ValueError(\"a desktop recording is already active; stop it first\")\n    folder = d.home / \"scratch\" / s.id / (\"video-\" + str(time.time_ns()))\n    s.recording = DesktopRecording(folder, float(p.get(\"seconds\", 20)))\n    return {\"effect_state\": \"committed\", \"recording\": True,\n            \"folder\": str(folder), \"temporary\": True}\n\n\ndef _record_stop(d: \"Daemon\", s: \"Session\") -> dict[str, Any]:\n    if s.recording is None:\n        raise ValueError(\"no desktop recording is active\")\n    result = s.recording.stop()\n    s.recording = None\n    from dataclasses import replace\n    from .contracts import EventKind, Observation, Parameter\n    context = replace(d.events.context(), source=Component.DESKTOP)\n    evidence = tuple(Parameter(key, str(Path(result[key]).relative_to(d.home)))\n                     for key in ('video', 'contact_sheet', 'analysis'))\n    d.events.emit(EventKind.OBSERVATION, Observation(\n        context.step_id, Component.DESKTOP, None, None, None,\n        (Parameter('diagnostic_kind', 'recording'), Parameter('frames', result['frames']), *evidence),\n        (), context), Component.DESKTOP)\n    return result\n");
